window.__ykCourses = window.__ykCourses || {};
window.__ykCourses.N2 = {"level":"N2","units":[{"n":1,"ja":"時・時点","en":"Time and timing","days":[{"title":"〜うちに・〜最中に"},{"title":"〜たとたん・〜かと思うと"},{"title":"〜次第・〜てからでないと"},{"title":"〜際（に）・〜に際して"},{"title":"〜にあたって・〜を機に"},{"title":"まとめ：似ている文法"}],"test":[]},{"n":2,"ja":"範囲・限定","en":"Scope and limits","days":[{"title":"〜に限って・〜に限らず"},{"title":"〜ばかりか・〜はもとより"},{"title":"〜から〜にかけて・〜にわたって"},{"title":"〜のみならず・〜に加えて"},{"title":"〜をはじめ・〜を中心に"},{"title":"まとめ：似ている文法"}],"test":[]},{"n":3,"ja":"原因・理由","en":"Cause and reason","days":[{"title":"〜ことから・〜につき","grammar":{"points":[{"id":"u03d1.p1","form":"〜ことから","gloss":"from the fact that (grounds, names)","connect":[{"pos":"動・い形","rule":"普通形 ＋ {ことから}"},{"pos":"な形","rule":"〜な／〜である ＋ {ことから}"},{"pos":"名詞","rule":"〜である／〜だった ＋ {ことから}"}],"examples":[{"ja":"この坂は、春になると桜がきれいに咲く{ことから}、「桜坂」と呼ばれている。","en":"Because the cherry trees bloom beautifully here in spring, this slope is called Sakura-zaka.","clip":"x_u03d1_p1_1"},{"ja":"部屋の電気がついていた{ことから}、まだ誰かが残っていると分かった。","en":"From the fact that the light in the room was on, I knew someone was still there.","clip":"x_u03d1_p1_2"}],"watch":{"note":"ことから gives the grounds for a judgement, a name or a conclusion. A request or an order cannot follow it; use から or ので for that.","bad":"雨が降っていることから、傘を持っていってください。","good":"雨が降っているから、傘を持っていってください。"}},{"id":"u03d1.p2","form":"〜につき","gloss":"due to (formal notices)","connect":[{"pos":"名詞","rule":"名詞 ＋ {につき}"},{"pos":"〜中","rule":"名詞 ＋ 中 ＋ {につき}"}],"examples":[{"ja":"店内改装{につき}、しばらくの間休業いたします。","en":"We are closed for a while due to refitting.","clip":"x_u03d1_p2_1"},{"ja":"工事中{につき}、こちらの出入口はご利用いただけません。","en":"Due to construction work, this entrance cannot be used.","clip":"x_u03d1_p2_2"}],"watch":{"note":"につき belongs on notices and in formal announcements. In casual talk with a friend, use から or ので.","bad":"風邪につき、今日は遊べないんだ。","good":"風邪だから、今日は遊べないんだ。"}}],"compare":{"intro":"All three give a reason. What changes is the kind of reason and where you meet it.","forms":[{"form":"〜ことから","tag":"根拠 · grounds for a judgement","mark":"dot","ja":"足跡が残っていた{ことから}、犯人は裏口から入ったとみられる。","en":"From the footprints, the thief is thought to have entered by the back door."},{"form":"〜につき","tag":"掲示・案内 · formal notice","mark":"dot","ja":"設備点検{につき}、午後は停電いたします。","en":"Due to an equipment check, the power will be off this afternoon."},{"form":"〜ため（に）","tag":"原因 · because of (neutral)","mark":"dot","ja":"大雪の{ため}、電車が止まった。","en":"The trains stopped because of heavy snow."}],"check":{"id":"u03d1.c1","kind":"choice","type":"文の文法1","label":"イベントのお知らせ","q":"当日は混雑が予想される（　　）、お早めにお越しください。","options":["ことから","につき","ため"],"answer":3,"why":["ことから backs a judgement or a name. A request like お越しください cannot follow it.","につき follows a noun, not a verb clause like 予想される.","ため follows a plain verb and can lead to a request on a notice."]}},"drill":[{"id":"u03d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"朝、道がぬれていた（　　）、^夜のうちに雨が降ったと分かった^。","options":["につき","ばかりに","ことから","あまり"],"answer":3,"why":["につき follows a noun and belongs on notices, not in a judgement like this.","ばかりに needs a result the speaker regrets. Finding something out is not one.","The wet road is the grounds, and 雨が降ったと分かった is the conclusion.","あまり is for a feeling or effort taken too far. A wet road is neither."]},{"id":"u03d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^本日は定休日^（　　）、営業しておりません。","options":["ことから","につき","あまり","からには"],"answer":2,"why":["After a noun, ことから needs である (定休日であることから), and it backs a judgement, not a shop notice.","A noun + につき: the formal reason on a notice.","あまり is for a feeling taken too far. 定休日 is not a feeling.","からには needs である after a noun, and a decision or duty after it."]},{"id":"u03d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この橋は、近くに大きな松の木がある（　　）、「松橋」と^呼ばれている^。","options":["ことから","につき","ばかりに","あまり"],"answer":1,"why":["The grounds for a name: 〜ことから〜と呼ばれている.","につき follows a noun, not a clause like 木がある.","ばかりに needs a result the speaker regrets. A name is not one.","あまり is for a feeling taken too far. A tree near a bridge is not one."]},{"id":"u03d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ただいま^館内工事中^（　　）、エレベーターは使用できません。","options":["のにつき","なことから","につき","のあまり"],"answer":3,"why":["No の here: につき follows the noun 工事中 directly.","工事中 is a noun, so 〜な does not attach to it. It would need である.","A noun + につき: the formal reason on a notice.","あまり is for a feeling taken too far. Construction work is not a feeling."]},{"id":"u03d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"窓ガラスが","after":"と考えられる。","tiles":["割れていた","ことから","犯人は","外から入った"],"star":2,"bank":[2,0,3,1],"hint":"Which tile can follow 窓ガラスが? The conclusion comes last, right before と考えられる.","full":"窓ガラスが割れていた{ことから}犯人は外から入ったと考えられる。","explain":"割れていた follows 窓ガラスが, and ことから follows the plain form. Then the conclusion: 犯人は, and 外から入った right before と考えられる."},{"id":"u03d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"台風","after":"とさせていただきます。","tiles":["接近","につき","本日の営業は","午後3時まで"],"star":2,"bank":[3,1,2,0],"hint":"につき follows a noun. Which tile is the noun that goes with 台風?","full":"台風接近{につき}本日の営業は午後3時までとさせていただきます。","explain":"台風接近 is one noun, and につき follows it. 本日の営業は is the topic, and 午後3時まで sits right before とさせていただきます."}],"exam":[{"id":"u03d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"彼は関西の言葉を話す（　　）、大阪の出身ではないかと思った。","options":["につき","ことから","からには","あまり"],"answer":2,"explain":"The way he speaks is the grounds for a guess, so ことから. につき follows a noun on a notice, からには needs a decision or duty after it, and あまり needs a feeling taken too far."},{"id":"u03d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この先、道路工事（　　）、車両は通行止めとなっております。","options":["ことから","にとって","につき","ばかりに"],"answer":3,"explain":"A noun + につき gives the reason on a notice. ことから and ばかりに would need である after a noun, and にとって gives a point of view, not a reason."},{"id":"u03d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"この島は、","after":"「かめ島」と呼ばれている。","tiles":["上から見ると","かめの","形をしている","ことから"],"star":2,"bank":[3,2,0,1],"full":"この島は、上から見るとかめの{形をしている}ことから「かめ島」と呼ばれている。","explain":"上から見ると, かめの, 形をしている, ことから. かめの describes 形, and ことから gives the grounds for the name, so it sits right before 「かめ島」."}]},"scene":{"ja":"駅と店の掲示","en":"Notices at the station and on shop fronts","intro":"Tap every notice word you would have to read.","words":[{"id":"closed","word":"休業","reading":"きゅうぎょう","gloss":"closed (for business)","parts":[["休","キュウ","rest: 休日"],["業","ギョウ","business: 営業"]],"clip":"s_u3d1_closed"},{"id":"works","word":"工事中","reading":"こうじちゅう","gloss":"under construction","parts":[["工事","こうじ","construction"],["中","チュウ","in progress: 会議中"]],"clip":"s_u3d1_works"},{"id":"special","word":"臨時","reading":"りんじ","gloss":"special, temporary","parts":[["臨","リン","for the occasion"],["時","ジ","time"]],"clip":"s_u3d1_special"},{"id":"noroad","word":"通行止め","reading":"つうこうどめ","gloss":"road closed","parts":[["通行","つうこう","passing through"],["止め","どめ","stopping"]],"clip":"s_u3d1_noroad"},{"id":"refit","word":"改装","reading":"かいそう","gloss":"refitting, renovation","parts":[["改","カイ","renew: 改札"],["装","ソウ","fit out: 服装"]],"clip":"s_u3d1_refit"},{"id":"hours","word":"営業時間","reading":"えいぎょうじかん","gloss":"opening hours","parts":[["営業","えいぎょう","business"],["時間","じかん","hours"]],"clip":"s_u3d1_hours"},{"id":"noentry","word":"立入禁止","reading":"たちいりきんし","gloss":"no entry","parts":[["立入","たちいり","entering"],["禁止","きんし","prohibited"]],"clip":"s_u3d1_noentry"},{"id":"step","word":"足元注意","reading":"あしもとちゅうい","gloss":"watch your step","parts":[["足元","あしもと","where you step"],["注意","ちゅうい","care"]],"clip":"s_u3d1_step"}],"check":{"id":"u03d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"店内_改装_のため、来週まで休業いたします。","options":["かいしょう","かいぞう","かいそう","こうそう"],"answer":3,"explain":"装 is ソウ here, as in 服装. かいぞう is a different word (改造, rebuilding), かいしょう is not this word, and 改 is never read こう."}},"skill":{"kind":"listening","ja":"即時応答","en":"Quick response","ask":"いちばんいい返事は？","item":{"id":"u03d1.r1","kind":"choice","type":"即時応答","label":"Quick response","q":"男：すみません、この入口、「工事中につき使用できません」って書いてあるんですけど……。","script":["男：すみません、この入口、「工事中につき使用できません」って書いてあるんですけど……。","女：はい、こちらの入口からどうぞ。","女：申し訳ございません。お手数ですが、裏の入口をご利用ください。","女：工事はいつ始まるんですか。"],"options":["はい、こちらの入口からどうぞ。","申し訳ございません。お手数ですが、裏の入口をご利用ください。","工事はいつ始まるんですか。"],"short":["こちらの入口からどうぞ","裏の入口をご利用ください","工事はいつ始まる？"],"answer":2,"why":["The notice says this entrance cannot be used, so she cannot invite him through it.","She apologises and sends him to another entrance, as the notice requires.","The notice says 工事中: the work has already started, and he is the one asking."],"clip":"l_u3d1"},"audio":[["M","すみません、この入口、「工事中につき使用できません」って書いてあるんですけど……。","すみません、このいりぐち、「工事中につき使用できません」って書いてあるんですけど……。"],["N","1",null],["F","はい、こちらの入口からどうぞ。","はい、こちらのいりぐちからどうぞ。"],["N","2",null],["F","申し訳ございません。お手数ですが、裏の入口をご利用ください。","申し訳ございません。お手数ですが、うらのいりぐちをご利用ください。"],["N","3",null],["F","工事はいつ始まるんですか。",null]]}},{"title":"〜以上（は）・〜からには","grammar":{"points":[{"id":"u03d2.p1","form":"〜以上（は）","gloss":"now that / since … (must, should)","connect":[{"pos":"動・い形","rule":"普通形 ＋ {以上（は）}"},{"pos":"な形・名詞","rule":"〜である／〜だった ＋ {以上（は）}"}],"examples":[{"ja":"締切を過ぎた{以上}、申込は受け付けられません。","en":"Since the deadline has passed, we cannot accept your application.","clip":"x_u03d2_p1_1"},{"ja":"会員である{以上は}、規則を守っていただきます。","en":"As long as you are a member, we ask you to follow the rules.","clip":"x_u03d2_p1_2"}],"watch":{"note":"The first part is a fact you cannot change. What follows is a judgement, a duty, a resolve or a request, not a plain report of what happened.","bad":"雨が降っている以上、試合は中止になった。","good":"雨が降っている以上、試合は中止にするしかない。"}},{"id":"u03d2.p2","form":"〜からには","gloss":"now that … (I will / I must)","connect":[{"pos":"動・い形","rule":"普通形 ＋ {からには}"},{"pos":"な形・名詞","rule":"〜である／〜だった ＋ {からには}"}],"examples":[{"ja":"留学する{からには}、日本語だけでなく専門の勉強もしっかりやりたい。","en":"Now that I am going to study abroad, I want to work hard at my subject as well as at Japanese.","clip":"x_u03d2_p2_1"},{"ja":"一度約束した{からには}、必ず守ります。","en":"Now that I have promised, I will keep my word.","clip":"x_u03d2_p2_2"}],"watch":{"note":"からには is not a plain \"because\". It needs a step that commits you before it, and a resolve, a duty or a strong wish after it. For an ordinary reason, use から.","bad":"疲れたからには、早く寝た。","good":"疲れたから、早く寝た。"}}],"compare":{"intro":"以上は and からには often swap freely, but 以上は tends to sound formal and logical and からには personal and determined, while ことから only gives the grounds for a judgement or a name.","forms":[{"form":"〜以上は","tag":"当然〜べき · given that, then","mark":"dot","ja":"契約を結んだ{以上は}、条件を守るべきだ。","en":"Once you have signed a contract, you should keep its terms."},{"form":"〜からには","tag":"決意 · now that, I will","mark":"dot","ja":"代表に選ばれた{からには}、全力を尽くしたい。","en":"Now that I have been chosen to represent us, I want to give it everything."},{"form":"〜ことから","tag":"根拠 · judging from the fact that","mark":"dot","ja":"署名がない{ことから}、この申込は無効だと判断された。","en":"Since there was no signature, the application was judged invalid."}],"check":{"id":"u03d2.c1","kind":"choice","type":"文の文法1","label":"山の名前","q":"形が富士山に似ている（　　）、この山は「北の富士」と呼ばれている。","options":["以上は","からには","ことから"],"answer":3,"why":["以上は leads to a duty, a resolve or a judgement. A name people use is none of these.","からには needs a resolve or a duty after it, and a name is neither.","ことから gives the grounds for a name: 〜ことから「…」と呼ばれている."]}},"drill":[{"id":"u03d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"契約書に署名する（　　）、^内容をよく理解しておくべきだ^。","options":["以上は","おかげで","ことから","わりに"],"answer":1,"why":["If you are going to sign, then you should understand it: a duty follows 以上は.","おかげで thanks a cause for a good result. A duty does not follow it.","ことから gives grounds taken from a known fact. Signing has not happened yet.","わりに contrasts: \"for something that …\". There is no contrast here."]},{"id":"u03d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"自分で^やると決めた^（　　）、^途中で投げ出すわけにはいかない^。","options":["おかげで","からには","ものの","ことから"],"answer":2,"why":["おかげで needs a good result after it, not a duty.","A decision that commits you, then \"I can't give up\": a resolve follows からには.","ものの means \"although\", and nothing here goes against the decision.","ことから gives grounds for a judgement about facts, not a personal duty like this."]},{"id":"u03d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^プロである^（　　）、^結果で評価されるのは当然だ^。","options":["わりに","以上","ものの","おかげで"],"answer":2,"why":["わりに sets up a surprise, and 当然だ says there is none.","Noun + である + 以上, then a judgement: 当然だ.","ものの means \"although\", but being a pro and being judged on results go together.","おかげで needs a good result after it. 当然だ is a judgement, not a result."]},{"id":"u03d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^日本で働く^（　　）、敬語くらいはきちんと^使えるようになりたい^。","options":["ものの","ことから","からには","わりに"],"answer":3,"why":["ものの means \"although\", and the wish does not go against working in Japan.","ことから does not lead to a wish like 〜たい.","A commitment (working in Japan), then a strong wish: からには.","わりに contrasts, and a wish does not contrast with working in Japan."]},{"id":"u03d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"一度仕事を","after":"通すべきだ。","tiles":["引き受けた","以上は","最後まで","やり"],"star":2,"bank":[3,0,2,1],"hint":"What does 仕事を need right after it? やり must sit right before 通す.","full":"一度仕事を引き受けた{以上は}最後までやり通すべきだ。","explain":"仕事を takes the verb 引き受けた, and 以上は follows it. やり joins 通す to make やり通す, so 最後まで comes just before やり."},{"id":"u03d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"試験を","after":"したい。","tiles":["受ける","からには","一回で","合格"],"star":1,"bank":[2,3,1,0],"hint":"試験を needs its verb first. Which noun goes with したい?","full":"試験を受ける{からには}一回で合格したい。","explain":"試験を受ける, then からには after the plain form. 合格 joins したい, and 一回で says how: 一回で合格したい."}],"exam":[{"id":"u03d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"会社の代表として出席する（　　）、個人的な意見を言うわけにはいかない。","options":["ものの","以上は","わりに","につき"],"answer":2,"explain":"Attending as the company's representative is a fact that brings a duty: 以上は. ものの and わりに set up a contrast that is not here, and につき follows a noun, not a verb."},{"id":"u03d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ここまで来た（　　）、もう後には引けない。","options":["おかげで","ものの","からには","ことから"],"answer":3,"explain":"Having come this far commits the speaker, and a resolve follows: からには. おかげで needs a good result, ものの means \"although\", and ことから gives grounds for a judgement, not a resolve."},{"id":"u03d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"親に","after":"ばかりはいられない。","tiles":["学費を","出してもらっている","以上","遊んで"],"star":2,"bank":[3,2,0,1],"full":"親に学費を出してもらっている{以上}遊んでばかりはいられない。","explain":"学費を, 出してもらっている, 以上, 遊んで. 以上 follows the verb, and 遊んで must sit right before ばかりはいられない."}]},"scene":{"ja":"学生寮の申込ページで","en":"On a student dorm application page","intro":"Tap every word you would have to understand before you sign up.","words":[{"id":"contract","word":"契約","reading":"けいやく","gloss":"contract","parts":[["契","ケイ","pledge: 契機"],["約","ヤク","promise: 約束"]],"clip":"s_u3d2_contract"},{"id":"apply","word":"申込","reading":"もうしこみ","gloss":"application","parts":[["申","もうし","say (humbly)"],["込","こみ","put in"]],"clip":"s_u3d2_apply"},{"id":"deadline","word":"締切","reading":"しめきり","gloss":"deadline (closing date)","parts":[["締","しめ","fasten, close"],["切","きり","cut off"]],"clip":"s_u3d2_deadline"},{"id":"limit","word":"期限","reading":"きげん","gloss":"time limit, due date","parts":[["期","キ","period: 期間"],["限","ゲン","limit: 制限"]],"clip":"s_u3d2_limit"},{"id":"renew","word":"更新","reading":"こうしん","gloss":"renewal","parts":[["更","コウ","change: 変更"],["新","シン","new"]],"clip":"s_u3d2_renew"},{"id":"cancel","word":"解約","reading":"かいやく","gloss":"cancelling a contract","parts":[["解","カイ","undo: 解決"],["約","ヤク","agreement"]],"clip":"s_u3d2_cancel"},{"id":"terms","word":"条件","reading":"じょうけん","gloss":"conditions, terms","parts":[["条","ジョウ","clause: 条約"],["件","ケン","matter: 事件"]],"clip":"s_u3d2_terms"},{"id":"sign","word":"署名","reading":"しょめい","gloss":"signature","parts":[["署","ショ","sign; office: 部署"],["名","メイ","name"]],"clip":"s_u3d2_sign"}],"check":{"id":"u03d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"書類の提出_期限_は三月十日です。","options":["きげん","きかん","ごげん","きけん"],"answer":1,"explain":"期限 is きげん: 期 is キ as in 期間, and 限 is ゲン as in 制限. きかん is 期間 (a period), きけん is 危険 (danger), and ごげん is not a reading of 期限."}},"skill":{"kind":"reading","ja":"理由","en":"Finding the reason","ask":"Why does the writer now read every contract to the end?","seconds":90,"passage":"以前の私は、契約書を最後まで読んだことがなかった。細かい字で書かれた条件は、どれも同じに見えたからだ。ところが、二年前に引っ越しをしようとして部屋の契約を解約したとき、思いがけない費用を請求された。期限の二か月前までに知らせなければ、一か月分の家賃を払うという条件があったのだ。確かに、署名した書類にはそう書いてあった。^それ以来^、私はどんな契約でも最後まで読むようにしている。自分で署名する以上は、知らなかったでは済まされない^からだ^。","strategy":"Find where the writer's habit changes (それ以来), then read the sentence that ends in からだ.","item":{"id":"u03d2.r1","kind":"choice","type":"読解・理由","q":"筆者が契約書を最後まで読むようになったのはなぜか。","options":["細かい字で書かれた条件は、どれも同じだとわかったから。","署名した以上、知らなかったでは済まないとわかったから。","部屋を貸す会社に、最後まで読むように言われたから。","解約の費用は払わなくてもいいと知ったから。"],"short":["条件はどれも同じ","知らなかったでは済まない","会社に言われた","解約の費用は払わなくていい"],"answer":2,"explain":"After それ以来 the writer states the new habit, and the next sentence gives its reason with 〜からだ.","why":["Option 1 is the writer's old view, the reason they used to skip the conditions.","","Option 3 is not in the text. Nobody told the writer to read contracts.","Option 4 is the opposite. The writer had to pay an unexpected cost."]}}},{"title":"〜だけに・〜だけあって","grammar":{"points":[{"id":"u03d3.p1","form":"〜だけに","gloss":"precisely because … all the more","connect":[{"pos":"動・い形","rule":"普通形 ＋ {だけに}"},{"pos":"な形","rule":"〜な／〜だった ＋ {だけに}"},{"pos":"名詞","rule":"名詞／〜だった ＋ {だけに}"}],"examples":[{"ja":"ずっと楽しみにしていた{だけに}、旅行が中止になって本当に残念だ。","en":"Because I had looked forward to it for so long, the trip being cancelled is all the more disappointing.","clip":"x_u03d3_p1_1"},{"ja":"このあたりは駅から近い{だけに}、家賃がかなり高い。","en":"Being so close to the station, this area has especially high rents.","clip":"x_u03d3_p1_2"}],"watch":{"note":"The cause makes the result especially natural or especially strong. For a plain cause and effect, use ので or から.","bad":"風邪をひいただけに、学校を休んだ。","good":"風邪をひいたので、学校を休んだ。"}},{"id":"u03d3.p2","form":"〜だけあって","gloss":"as you would expect of …","connect":[{"pos":"動・い形","rule":"普通形 ＋ {だけあって}"},{"pos":"な形","rule":"〜な／〜だった ＋ {だけあって}"},{"pos":"名詞","rule":"名詞 ＋ {だけあって}"}],"examples":[{"ja":"さすが十年も日本に住んでいる{だけあって}、彼の日本語はとても自然だ。","en":"As you would expect of someone who has lived in Japan for ten years, his Japanese is very natural.","clip":"x_u03d3_p2_1"},{"ja":"毎日練習している{だけあって}、彼女のピアノは本当にうまい。","en":"She practises every day, and it shows: her piano playing is really good.","clip":"x_u03d3_p2_2"}],"watch":{"note":"The result lives up to the cause, so it is praise. For a disappointing result, use だけに.","bad":"高かっただけあって、すぐに壊れてしまった。","good":"高かっただけに、すぐに壊れてしまってショックだった。"}}],"compare":{"intro":"All three link a cause to a result. What changes is whether the result is praise, all the more so, or a regret.","forms":[{"form":"〜だけに","tag":"なおさら · all the more","mark":"dot","ja":"期待していた{だけに}、結果にがっかりした。","en":"Having expected so much, I was all the more disappointed by the result."},{"form":"〜だけあって","tag":"さすが · lives up to it","mark":"dot","ja":"何度も練習した{だけあって}、発表は大成功だった。","en":"As you would expect after so much practice, the talk was a great success."},{"form":"〜ばかりに","tag":"悪い結果 · just because","mark":"down","ja":"一度練習を休んだ{ばかりに}、発表で失敗した。","en":"Just because I skipped one rehearsal, my talk went wrong."}],"check":{"id":"u03d3.c1","kind":"choice","type":"文の文法1","label":"コンサートの日","q":"ずっと楽しみにしていた（　　）、コンサートが中止になって本当に残念だ。","options":["ばかりに","だけあって","だけに"],"answer":3,"why":["ばかりに says the cause brought about the bad result. Looking forward to it did not cause the cancellation.","だけあって praises a result that lives up to the cause. A cancellation is not praise.","Because she had looked forward to it, the disappointment is all the more."]}},"drill":[{"id":"u03d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^さすが^一流ホテル（　　）、^サービスがすばらしい^。","options":["ばかりに","あまり","だけあって","からには"],"answer":3,"why":["ばかりに needs a bad result the speaker regrets, and it does not follow a noun directly.","あまり follows a feeling noun with の, as in 心配のあまり. 一流ホテル is not a feeling.","さすが with a status, and a result that lives up to it: praise.","からには needs a decision or duty after it, and 一流ホテル would need である before it."]},{"id":"u03d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^期待が大きかった^（　　）、負けたときの^ショックも大きかった^。","options":["からには","だけあって","わりに","だけに"],"answer":4,"why":["からには needs a decision or duty after it, not a feeling that has already happened.","だけあって praises. A painful shock is not a result anyone praises.","わりに sets up a contrast, but a big hope and a big shock go together.","The bigger the hope, the bigger the shock: も marks the \"all the more\"."]},{"id":"u03d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^毎日五時間も練習している^（　　）、彼女の演奏は^見事だった^。","options":["ばかりに","だけあって","あまり","ものの"],"answer":2,"why":["ばかりに leads to a bad result. 見事だった is praise.","Hard practice, and a performance that lives up to it.","あまり is \"too much, so something went wrong\". Here nothing went wrong.","ものの means \"although\", but the practice and the fine performance do not contrast."]},{"id":"u03d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^ふだんおとなしい^彼（　　）、急に大声を出したときは^みんな驚いた^。","options":["だけに","だけあって","ばかりに","からには"],"answer":1,"why":["Because he is usually so quiet, the shout was all the more surprising.","だけあって means the result is what you would expect. Here everyone was surprised.","ばかりに does not follow a noun directly, and his being quiet did not cause the shout.","からには does not follow a noun directly, and it needs a decision or duty after it."]},{"id":"u03d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"初めての海外旅行","after":"新鮮に感じられた。","tiles":["だった","だけに","見るもの","すべてが"],"star":2,"bank":[2,1,3,0],"hint":"だけに follows a plain form here. Which tile turns 旅行 into one?","full":"初めての海外旅行だった{だけに}見るものすべてが新鮮に感じられた。","explain":"旅行だった is the plain past, so だけに comes right after it. 見るものすべてが is \"everything I saw\", and it is the subject of 新鮮に感じられた."},{"id":"u03d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"さすが","after":"できていた。","tiles":["人気の","店","だけあって","行列が"],"star":1,"bank":[3,2,0,1],"hint":"だけあって can follow a noun directly. Which noun is さすが about?","full":"さすが人気の{店}だけあって行列ができていた。","explain":"人気の describes 店, and 店 takes だけあって directly. 行列が goes with できていた."}],"exam":[{"id":"u03d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"このかばんは有名なブランドの製品（　　）、十年使っても少しも傷んでいない。","options":["だけあって","ばかりに","にしては","あまり"],"answer":1,"explain":"A famous brand, and a bag that lives up to it: だけあって, which can follow a noun directly. ばかりに needs a bad result, にしては sets up a contrast with what you would expect, and あまり needs a feeling noun with の."},{"id":"u03d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"彼女は小さいころからずっと努力してきた（　　）、今回の不合格はとても悔しいだろう。","options":["だけあって","だけに","ばかりに","くせに"],"answer":2,"explain":"Years of effort make the failure all the more painful: だけに. だけあって needs a good result, ばかりに needs a cause that brought the result about, and くせに criticises someone."},{"id":"u03d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"ベテランの","after":"みんな驚いた。","tiles":["山田さん","だけに","今回の","ミスには"],"star":2,"bank":[3,0,2,1],"full":"ベテランの山田さんだけに{今回の}ミスにはみんな驚いた。","explain":"山田さん, だけに, 今回の, ミスには. ベテランの describes 山田さん, だけに follows the noun directly, and 今回の must sit right before ミスには."}]},"scene":{"ja":"病院で","en":"At the clinic","intro":"Tap every sign you would have to read.","words":[{"id":"desk","word":"受付","reading":"うけつけ","gloss":"reception","parts":[["受","うけ","receive"],["付","つけ","attach"]],"clip":"s_u3d3_desk"},{"id":"exam","word":"診察","reading":"しんさつ","gloss":"medical examination","parts":[["診","シン","examine"],["察","サツ","observe: 観察"]],"clip":"s_u3d3_exam"},{"id":"wait","word":"待合室","reading":"まちあいしつ","gloss":"waiting room","parts":[["待合","まちあい","waiting"],["室","シツ","room: 教室"]],"clip":"s_u3d3_wait"},{"id":"rx","word":"処方箋","reading":"しょほうせん","gloss":"prescription","parts":[["処方","しょほう","prescribing"],["箋","セン","slip of paper"]],"clip":"s_u3d3_rx"},{"id":"pharm","word":"薬局","reading":"やっきょく","gloss":"pharmacy","parts":[["薬","やっ","medicine (ヤク, here やっ)"],["局","キョク","office: 郵便局"]],"clip":"s_u3d3_pharm"},{"id":"pay","word":"会計","reading":"かいけい","gloss":"payment, the cashier","parts":[["会","カイ","meet"],["計","ケイ","count: 計算"]],"clip":"s_u3d3_pay"},{"id":"book","word":"予約","reading":"よやく","gloss":"appointment, booking","parts":[["予","ヨ","in advance: 予定"],["約","ヤク","promise"]],"clip":"s_u3d3_book"},{"id":"intmed","word":"内科","reading":"ないか","gloss":"internal medicine","parts":[["内","ナイ","inside"],["科","カ","department: 外科"]],"clip":"s_u3d3_intmed"}],"check":{"id":"u03d3.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"名前を呼ばれるまで、_待合室_でお待ちください。","options":["まちあいしつ","まちごうしつ","たいごうしつ","まちあいじつ"],"answer":1,"explain":"待合室 is まちあいしつ: 待ち合い (kun) + 室 (しつ). 合 is not read ごう here, 待 is not read たい, and 室 does not become じつ."}},"skill":{"kind":"listening","ja":"ポイント理解","en":"Point comprehension","ask":"女の人はどうしてこの病院に通うことにしましたか。","strategy":"Read the four choices first. The first reason you hear is often not the real one: wait for words like でも or 決めたのは.","item":{"id":"u03d3.r1","kind":"choice","type":"ポイント理解","q":"女の人はどうしてこの病院に通うことにしましたか。","script":["ナレーター：病院の待合室で、男の人と女の人が話しています。女の人はどうしてこの病院に通うことにしましたか。","男：あれ、田中さん。この病院に来てるんですか。","女：ええ、先月から。前は駅前の内科に通ってたんですけど。","男：駅前のほうが近いのに。先生が合わなかったんですか。","女：いえ、先生はとても親切でしたよ。ただ、予約ができなくて、いつも一時間以上待たされたんです。","男：ここは建物も新しくて、きれいですよね。","女：ええ。でも、決めたのはネットで予約できるからなんです。おかげで、待ち時間がほとんどなくて。","男：なるほど。少し遠くても、そのほうが楽ですね。","ナレーター：女の人はどうしてこの病院に通うことにしましたか。"],"options":["駅前の内科の先生が親切ではなかったから","予約ができて、待ち時間が短いから","建物が新しくて、きれいだから","家から近くて、通いやすいから"],"printed":true,"short":["先生が親切ではなかった","予約ができて待たない","建物が新しくてきれい","家から近い"],"answer":2,"why":["She says the doctor there was very kind.","決めたのは…からなんです gives her reason: online booking, and almost no waiting.","She agrees the building is nice, then says でも: that is not why she chose it.","The station clinic is the closer one. This one is a little far (少し遠くても)."],"clip":"l_u3d3"},"audio":[["N","病院の待合室で、男の人と女の人が話しています。女の人はどうしてこの病院に通うことにしましたか。",null],["M","あれ、田中さん。この病院に来てるんですか。","あれ、たなかさん。このびょういんにきてるんですか。"],["F","ええ、先月から。前は駅前の内科に通ってたんですけど。",null],["M","駅前のほうが近いのに。先生が合わなかったんですか。",null],["F","いえ、先生はとても親切でしたよ。ただ、予約ができなくて、いつも一時間以上待たされたんです。","いえ、せんせいはとてもしんせつでしたよ。ただ、よやくができなくて、いつもいちじかんいじょうまたされたんです。"],["M","ここは建物も新しくて、きれいですよね。",null],["F","ええ。でも、決めたのはネットで予約できるからなんです。おかげで、待ち時間がほとんどなくて。",null],["M","なるほど。少し遠くても、そのほうが楽ですね。",null],["N","女の人はどうしてこの病院に通うことにしましたか。",null]]}},{"title":"〜ばかりに・〜あまり","grammar":{"points":[{"id":"u03d4.p1","form":"〜ばかりに","gloss":"just because … (bad result)","connect":[{"pos":"動・い形","rule":"普通形 ＋ {ばかりに}"},{"pos":"な形","rule":"〜な／〜だった ＋ {ばかりに}"},{"pos":"名詞","rule":"〜である／〜だった ＋ {ばかりに}"}],"examples":[{"ja":"メールをよく読まなかった{ばかりに}、会議の時間を間違えた。","en":"Just because I didn't read the email properly, I got the meeting time wrong.","clip":"t_ex1"},{"ja":"[油断|ゆだん]した{ばかりに}、最後に[逆転|ぎゃくてん]されてしまった。","en":"Just because I let my guard down, I was overtaken at the very end.","clip":"t_ex2"}],"watch":{"note":"What follows is a bad result that the speaker regrets. For a good result, use おかげで.","bad":"毎日練習したばかりに、優勝できた。","good":"毎日練習したおかげで、優勝できた。"}},{"id":"u03d4.p2","form":"〜あまり","gloss":"so … that (too much of a feeling)","connect":[{"pos":"名詞","rule":"名詞 ＋ の ＋ {あまり}"},{"pos":"動詞","rule":"辞書形／た形 ＋ {あまり}"},{"pos":"な形","rule":"〜な ＋ {あまり}"}],"examples":[{"ja":"試合に負けた悔しさの{あまり}、一晩中眠れなかった。","en":"I was so frustrated at losing the match that I could not sleep all night.","clip":"x_u03d4_p2_1"},{"ja":"合格を急ぐ{あまり}、基礎をおろそかにしてしまった。","en":"In my hurry to pass, I neglected the basics.","clip":"x_u03d4_p2_2"}],"watch":{"note":"A feeling or an effort goes too far, and something unusual or unwanted happens. What follows is a result, never a request or a plan.","bad":"心配のあまり、電話してください。","good":"心配のあまり、何度も電話してしまった。"}}],"compare":{"intro":"All three give a cause. What changes is how that cause leads to what follows.","forms":[{"form":"〜ばかりに","tag":"悪い結果 · just because","mark":"down","ja":"準備不足だった{ばかりに}、発表で失敗した。","en":"Just because I was underprepared, my talk failed."},{"form":"〜あまり","tag":"〜すぎて · so much that","mark":"up","ja":"緊張の{あまり}、発表中に声が出なくなった。","en":"So nervous that my voice gave out mid-talk."},{"form":"〜だけに","tag":"なおさら · all the more","mark":"dot","ja":"何度も練習した{だけに}、失敗がくやしい。","en":"After so much practice, failing hurts all the more."}],"check":{"id":"u03d4.c1","kind":"choice","type":"文の文法1","label":"合格発表の日","q":"うれしさの（　　）、思わず大声を出した。","options":["ばかりに","あまり","だけに"],"answer":2,"why":["ばかりに cannot follow の, and nothing here is regretted.","A feeling as a noun + の + あまり.","だけに cannot follow の."]}},"drill":[{"id":"u03d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"寝坊した（　　）、^大事な試験を受けられなかった^。","options":["ばかりに","あまり","だけあって","からには"],"answer":1,"why":["One cause, and a bad result the speaker regrets.","A feeling or state taken to an extreme, as in 緊張のあまり. 寝坊した is one event.","Praise: a good result that lives up to its cause.","\"Now that…\": a decision or duty follows, not a result."]},{"id":"u03d4.d2","kind":"star","type":"文の文法2","label":"Build the sentence","before":"面接では、緊張","after":"言い間違えてしまった。","tiles":["の","あまり","自分の","名前まで"],"star":2,"bank":[2,1,3,0],"hint":"あまり comes after a noun with の. Which tile can sit right after 緊張?","full":"面接では、緊張の{あまり}自分の名前まで言い間違えてしまった。","explain":"緊張 takes の before あまり, so the first two tiles are fixed. 自分の has to sit right before 名前まで."},{"id":"u03d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"母は^心配の^（　　）、夜も眠れなかったそうだ。","options":["ばかりに","あまり","だけに","からには"],"answer":2,"why":["ばかりに does not follow a noun with の.","A feeling as a noun + の + あまり, and a result that goes too far.","だけに does not follow の either; it would need 心配なだけに.","からには needs a clause, and a decision or duty after it."]},{"id":"u03d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"値段の安さだけで選んだ（　　）、^すぐに壊れるパソコンを買ってしまった^。","options":["だけあって","ばかりに","からには","ことから"],"answer":2,"why":["だけあって praises: the result lives up to the cause. Here the result is bad.","One careless choice, and a result the speaker regrets.","からには needs a decision or duty after it, not a result.","ことから gives grounds for a judgement or a name, not the cause of a regret."]},{"id":"u03d4.d5","kind":"choice","type":"文の文法1","label":"Choose the form","q":"子どもの将来を^考える^（　　）、親が何でも決めてしまうのはよくない。","options":["あまり","ばかりに","だけに","ことから"],"answer":1,"why":["Thinking about the future too much, and something goes wrong: dictionary form + あまり.","ばかりに needs a concrete cause and a regretted result. Here the sentence judges a habit.","だけに means \"all the more because\", which does not fit a warning.","ことから gives grounds for a judgement; thinking about the future is not grounds for よくない."]},{"id":"u03d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"朝、","after":"家に忘れてきた。","tiles":["急ぐ","あまり","大事な","書類を"],"star":2,"bank":[3,0,2,1],"hint":"Which verb can sit before あまり? The thing forgotten comes right before 家に.","full":"朝、急ぐ{あまり}大事な書類を家に忘れてきた。","explain":"急ぐ in the dictionary form goes before あまり. 大事な describes 書類, and 書類を is what was left at home."}],"exam":[{"id":"u03d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"説明書をよく読まなかった（　　）、新しいパソコンを壊してしまった。","options":["だけあって","ばかりに","わりに","からには"],"answer":2,"explain":"A single cause and a result the speaker regrets. だけあって praises, わりに contrasts, and からには needs a decision after it."},{"id":"u03d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"突然の知らせを聞いた彼女は、驚き（　　）、持っていたコップを落としてしまった。","options":["のあまり","ばかりに","だけあって","からには"],"answer":1,"explain":"Noun + の + あまり: a feeling so strong that something unusual happens. ばかりに and からには need a clause before them, and だけあって praises."},{"id":"u03d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"うそを","after":"失ってしまった。","tiles":["ついた","ばかりに","友人の","信頼を"],"star":2,"bank":[3,0,2,1],"full":"うそをついたばかりに{友人の}信頼を失ってしまった。","explain":"ついた, ばかりに, 友人の, 信頼を. ばかりに follows the plain form, and 友人の must sit right before 信頼を."}]},"scene":{"ja":"市役所で","en":"At the city office","intro":"Tap every sign you would have to read.","words":[{"id":"resid","word":"住民票","reading":"じゅうみんひょう","gloss":"residence certificate","parts":[["住民","じゅうみん","residents"],["票","ヒョウ","slip, ballot"]],"clip":"s_resid"},{"id":"cert","word":"証明書","reading":"しょうめいしょ","gloss":"certificate","parts":[["証明","しょうめい","proof"],["書","ショ","document"]],"clip":"s_cert"},{"id":"reissue","word":"再発行","reading":"さいはっこう","gloss":"reissue, a replacement","parts":[["再","サイ","again: 再開"],["発行","はっこう","issue"]],"clip":"s_reissue"},{"id":"ticket","word":"番号札","reading":"ばんごうふだ","gloss":"number ticket","parts":[["番号","ばんごう","number"],["札","ふだ","tag, ticket"]],"clip":"s_ticket"},{"id":"form","word":"申請書","reading":"しんせいしょ","gloss":"application form","parts":[["申請","しんせい","application"],["書","ショ","document"]],"clip":"s_form"},{"id":"sample","word":"記入例","reading":"きにゅうれい","gloss":"filled-in sample","parts":[["記入","きにゅう","filling in"],["例","レイ","example"]],"clip":"s_sample"},{"id":"fee","word":"手数料","reading":"てすうりょう","gloss":"handling fee","parts":[["手数","てすう","trouble"],["料","リョウ","fee: 送料"]],"clip":"s_fee"},{"id":"ident","word":"本人確認","reading":"ほんにんかくにん","gloss":"identity check","parts":[["本人","ほんにん","the person"],["確認","かくにん","check"]],"clip":"s_ident"}],"check":{"id":"u03d4.k1","kind":"choice","type":"語形成","label":"How the exam asks it","q":"カードの（　　）発行を申し込んだ。","options":["再","復","改","重"],"answer":1,"explain":"再 is \"again\": 再発行, 再開, 再試験. 復 appears in 復習 but is not a prefix, 改 makes 改正 and 改札, and 重 is not used this way."}},"skill":{"kind":"reading","ja":"筆者の考え","en":"The writer's view","ask":"Where is the writer's own view?","seconds":90,"passage":"最近は、わからないことがあると、すぐにスマートフォンで検索する人が多い。確かに、答えは数秒で見つかる。^しかし^、苦労せずに手に入れた答えは、記憶に残りにくいものだ。多少時間がかかるとしても、まずは自分の頭で考えてみる。そうした過程を経てこそ、知識は身につく^のではないだろうか^。","strategy":"Skip what \"many people\" do. Look after しかし, and at how the last sentence ends.","item":{"id":"u03d4.r1","kind":"choice","type":"読解・筆者の考え","q":"筆者の考えに合うのはどれか。","options":["検索することは時間のむだだ。","まず自分で考えたほうが身につく。","すぐ見つかる答えは信用できない。","わからないことはすぐ検索すべきだ。"],"short":["検索は時間のむだ","自分で考えたほうが身につく","すぐ見つかる答えは信用できない","すぐ検索すべきだ"],"answer":2,"explain":"The writer's own view follows しかし. The ending 〜のではないだろうか offers it as an opinion.","why":["Option 1 goes too far. The writer accepts that searching finds the answer in seconds.","","Option 3 is not in the text. Such answers are hard to remember, not wrong.","Option 4 is what many people do in the first sentence, not what the writer advises."]}}},{"title":"〜のことだから・〜ことだし","grammar":{"points":[{"id":"u03d5.p1","form":"〜のことだから","gloss":"knowing X, (I expect) …","connect":[{"pos":"名詞（人）","rule":"名詞 ＋ {のことだから}"},{"pos":"後ろ","rule":"{のことだから}、〜だろう／〜に違いない／〜はずだ"}],"examples":[{"ja":"時間に厳しい山田さん{のことだから}、もう駅に着いているだろう。","en":"Knowing how strict Yamada-san is about time, she's probably at the station already.","clip":"x_u03d5_p1_1"},{"ja":"[心配性|しんぱいしょう]の母{のことだから}、何度も電話してくるに違いない。","en":"Knowing what a worrier my mother is, she's sure to call again and again.","clip":"x_u03d5_p1_2"}],"watch":{"note":"The noun before のことだから is a person (or a group) whose character the speaker knows, and a guess follows. A plain reason like the weather takes から.","bad":"大雨のことだから、試合は中止だろう。","good":"大雨だから、試合は中止だろう。"}},{"id":"u03d5.p2","form":"〜ことだし","gloss":"since …, (let's / I'll) …","connect":[{"pos":"動・い形","rule":"普通形 ＋ {ことだし}"},{"pos":"な形・名詞","rule":"〜な／〜である ＋ {ことだし}"}],"examples":[{"ja":"雨も止んだ{ことだし}、そろそろ出かけようか。","en":"The rain has stopped, so shall we head out?","clip":"x_u03d5_p2_1"},{"ja":"仕事も一段落した{ことだし}、今夜は早く帰ることにしよう。","en":"Work has calmed down, so I'll go home early tonight.","clip":"x_u03d5_p2_2"}],"watch":{"note":"ことだし gives one reason among others, and what follows is a suggestion, a decision or a wish. For a result that simply happened, use から or ので.","bad":"雨が降ったことだし、試合が中止になった。","good":"雨が降ったので、試合が中止になった。"}}],"compare":{"intro":"All three give a reason. What changes is what the reason is and what comes after it.","forms":[{"form":"〜のことだから","tag":"人柄から推測 · knowing X","mark":"dot","ja":"慎重な兄{のことだから}、遅延も考えて早めに家を出ただろう。","en":"Knowing how careful my brother is, he'll have left early in case of delays."},{"form":"〜ことだし","tag":"理由の一つ・提案 · since…, let's","mark":"dot","ja":"終電も近い{ことだし}、今日はこの辺で帰ろう。","en":"The last train is coming up, so let's call it a night."},{"form":"〜以上は","tag":"当然・決意 · now that…, must","mark":"dot","ja":"約束した{以上は}、遅れるわけにはいかない。","en":"Now that I've promised, I can't be late."}],"check":{"id":"u03d5.c1","kind":"choice","type":"文の文法1","label":"旅行の前の日","q":"準備のいい兄（　　）、もう明日の乗り換えを調べてあるだろう。","options":["のことだから","ことだし","以上は"],"answer":1,"why":["A person whose character you know (準備のいい兄), then a guess with だろう.","ことだし cannot follow a noun directly; it would need である, and it leads to a suggestion, not a guess.","以上は cannot follow a noun directly either, and it leads to a duty or resolve, not a guess about someone."]}},"drill":[{"id":"u03d5.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"仕事の早い^彼女^（　　）、もう資料を全部そろえている^はずだ^。","options":["からには","ばかりに","のことだから","あまり"],"answer":3,"why":["からには cannot follow a noun directly, and it leads to a duty or resolve.","ばかりに cannot follow a noun directly, and it needs a result the speaker regrets.","A person you know well (仕事の早い彼女), then a confident guess with はずだ.","あまり follows a feeling noun with の, as in 心配のあまり. 彼女 is a person."]},{"id":"u03d5.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"バスも^もうすぐ来る^（　　）、そろそろバス停に^行こうか^。","options":["ことだし","以上は","のことだから","ばかりに"],"answer":1,"why":["One reason (the bus is coming soon), then a casual suggestion with 〜ようか.","A bus about to come is not a commitment that binds anyone, so 以上は sounds wrong here.","のことだから follows a noun for a person, not a verb.","ばかりに needs a bad result the speaker regrets, not a suggestion."]},{"id":"u03d5.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"せっかく天気もいい（　　）、^歩いて帰ることにした^。","options":["あまり","ことだし","のことだから","ばかりに"],"answer":2,"why":["あまり means a feeling or state goes too far and something unwanted happens. A calm decision does not fit.","One reason (good weather), then a decision with ことにした. も hints that there are other reasons too.","のことだから follows a noun for a person, not an adjective.","ばかりに needs a result the speaker regrets. Walking home is a choice, not a regret."]},{"id":"u03d5.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^時間にルーズな^佐藤さん（　　）、今日も遅刻する^に違いない^。","options":["ことだし","以上は","ばかりに","のことだから"],"answer":4,"why":["ことだし cannot follow a noun directly, and it leads to a suggestion, not a guess.","以上は cannot follow a noun directly, and it leads to a duty or resolve.","ばかりに cannot follow a noun directly, and nothing has happened yet to regret.","Sato-san's known habit (時間にルーズ), then a guess with に違いない."]},{"id":"u03d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あの","after":"時間どおりに来るだろう。","tiles":["まじめな","山田さんの","ことだから","きっと"],"star":1,"bank":[2,3,0,1],"hint":"Which tile describes the person? のことだから comes right after the person.","full":"あのまじめな山田さんの{ことだから}きっと時間どおりに来るだろう。","explain":"あの and まじめな both describe 山田さん, and 山田さんの joins ことだから. きっと sits before the guess."},{"id":"u03d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"せっかく","after":"温泉にでも入って帰ろう。","tiles":["遠く","まで","来た","ことだし"],"star":2,"bank":[3,1,0,2],"hint":"ことだし follows a plain-form verb. What did we do that makes this a good idea?","full":"せっかく遠くまで来た{ことだし}温泉にでも入って帰ろう。","explain":"遠くまで来た is the reason, in the plain form before ことだし. The suggestion 帰ろう follows."}],"exam":[{"id":"u03d5.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"子どもが好きな佐藤さん（　　）、きっといい先生になるだろう。","options":["ことだし","以上は","のことだから","ばかりに"],"answer":3,"explain":"A person whose character the speaker knows, then a guess with だろう: のことだから. ことだし, 以上は and ばかりに cannot follow a noun directly, and none of them leads to a guess like this."},{"id":"u03d5.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"今日はみんな疲れている（　　）、打ち上げは来週にしませんか。","options":["のことだから","ことだし","あまり","ばかりに"],"answer":2,"explain":"One reason, then a suggestion (〜ませんか): ことだし. のことだから follows a noun for a person. あまり and ばかりに lead to a result that has happened, not a suggestion."},{"id":"u03d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"雨も","after":"帰りましょうか。","tiles":["強く","なってきた","ことだし","暗くなる前に"],"star":1,"bank":[3,0,2,1],"full":"雨も強く{なってきた}ことだし暗くなる前に帰りましょうか。","explain":"強く, なってきた, ことだし, 暗くなる前に. 強くなってきた is the reason before ことだし, and 暗くなる前に goes with 帰りましょうか."}]},"scene":{"ja":"駅で","en":"At the station","intro":"Tap every word you would read on the boards and signs.","words":[{"id":"transfer","word":"乗換","reading":"のりかえ","gloss":"change (of trains)","parts":[["乗","のり","ride"],["換","かえ","change"]],"clip":"s_u3d5_transfer"},{"id":"gate","word":"改札口","reading":"かいさつぐち","gloss":"ticket gate","parts":[["改札","かいさつ","ticket check"],["口","ぐち","opening, way out"]],"clip":"s_u3d5_gate"},{"id":"suspend","word":"運休","reading":"うんきゅう","gloss":"service suspended","parts":[["運","ウン","run: 運転"],["休","キュウ","rest: 休日"]],"clip":"s_u3d5_suspend"},{"id":"delay","word":"遅延","reading":"ちえん","gloss":"delay","parts":[["遅","チ","late: 遅刻"],["延","エン","extend: 延長"]],"clip":"s_u3d5_delay"},{"id":"local","word":"各駅停車","reading":"かくえきていしゃ","gloss":"local train (stops at every station)","parts":[["各駅","かくえき","every station"],["停車","ていしゃ","stopping"]],"clip":"s_u3d5_local"},{"id":"rapid","word":"快速","reading":"かいそく","gloss":"rapid train","parts":[["快","カイ","pleasant, brisk: 快適"],["速","ソク","speed: 速度"]],"clip":"s_u3d5_rapid"},{"id":"last","word":"終電","reading":"しゅうでん","gloss":"last train","parts":[["終","シュウ","end: 終点"],["電","デン","electric (train): 電車"]],"clip":"s_u3d5_last"},{"id":"fare","word":"運賃","reading":"うんちん","gloss":"fare","parts":[["運","ウン","carry: 運送"],["賃","チン","fee, wage: 家賃"]],"clip":"s_u3d5_fare"}],"check":{"id":"u03d5.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"大雨の影響で、電車に_遅延_が発生しています。","options":["ちいん","ちえん","じえん","ちえい"],"answer":2,"explain":"遅 is チ as in 遅刻, and 延 is エン as in 延長: ちえん. ちいん and ちえい get 延 wrong, and じえん gets 遅 wrong."}},"skill":{"kind":"listening","ja":"課題理解","en":"Task comprehension","ask":"男の学生はこのあとまず何をしますか。","audio":[["N","大学で、男の学生と女の学生が、ゼミの発表の準備について話しています。男の学生はこのあとまず何をしますか。","大学で、男の学生と女の学生が、ゼミの発表の準備について話しています。男の学生はこのあとまずなにをしますか。"],["M","来週の発表のスライド、だいたいできたよ。ただ、グラフの数字がひとつ合わないんだ。",null],["F","あ、それなら、田中さんにデータを確認してもらうように、さっき私から頼んでおいたよ。",null],["M","ありがとう。じゃあ、すぐスライドを直せるね。",null],["F","でも、田中さん、今日はアルバイトで、返事は夜になるって。",null],["M","そうか。まあ、田中さんのことだから、今夜中にはちゃんと調べてくれるだろうね。","そうか。まあ、田中さんのことだから、こんやじゅうにはちゃんと調べてくれるだろうね。"],["F","うん。じゃあ、待っている間に、配るレジュメを作っちゃえば？時間もあることだし。",null],["M","そうだね。数字は後で入れることにして、そうするよ。先生に送るのは、全部そろってからでいいよね。",null],["F","うん、それでいいと思う。",null],["N","男の学生はこのあとまず何をしますか。","男の学生はこのあとまずなにをしますか。"]],"item":{"id":"u03d5.r1","kind":"choice","type":"課題理解","q":"男の学生はこのあとまず何をしますか。","script":["ナレーター：大学で、男の学生と女の学生が、ゼミの発表の準備について話しています。男の学生はこのあとまず何をしますか。","男：来週の発表のスライド、だいたいできたよ。ただ、グラフの数字がひとつ合わないんだ。","女：あ、それなら、田中さんにデータを確認してもらうように、さっき私から頼んでおいたよ。","男：ありがとう。じゃあ、すぐスライドを直せるね。","女：でも、田中さん、今日はアルバイトで、返事は夜になるって。","男：そうか。まあ、田中さんのことだから、今夜中にはちゃんと調べてくれるだろうね。","女：うん。じゃあ、待っている間に、配るレジュメを作っちゃえば？時間もあることだし。","男：そうだね。数字は後で入れることにして、そうするよ。先生に送るのは、全部そろってからでいいよね。","女：うん、それでいいと思う。","ナレーター：男の学生はこのあとまず何をしますか。"],"options":["田中さんにデータの確認を頼む","スライドの数字を直す","レジュメを作る","先生にレジュメを送る"],"printed":true,"short":["田中さんに頼む","スライドを直す","レジュメを作る","先生に送る"],"answer":3,"why":["Already done: the woman asked Tanaka-san a moment ago.","Later: he can fix the numbers only after Tanaka-san replies tonight.","He agrees to make the handout while he waits, and to fill in the numbers later.","Later: he will send it to the teacher once everything is ready."],"clip":"l_u3d5"}}},{"title":"まとめ：似ている文法","grammar":{"points":[],"compare":{"intro":"Ask two questions: what comes before the form (a person, a noun or a clause), and what comes after it (a judgement, a notice, a duty or resolve, praise, a regret, a guess or a suggestion). Together they leave only one of the ten.","forms":[{"form":"〜ことから","tag":"根拠 · grounds for a judgement","mark":"dot","ja":"机の上にかぎが置いてあった{ことから}、父はもう帰っていると分かった。","en":"The keys were on the desk, so I knew Dad was already home."},{"form":"〜につき","tag":"掲示・案内 · formal notice","mark":"dot","ja":"売り切れ{につき}、本日の販売は終了いたしました。","en":"Sold out: today's sales have ended."},{"form":"〜以上（は）","tag":"当然〜べき · given that, then","mark":"dot","ja":"お金を借りた{以上は}、約束の日までに返すべきだ。","en":"Once you borrow money, you should pay it back by the agreed day."},{"form":"〜からには","tag":"決意 · now that, I will","mark":"dot","ja":"自分の店を開く{からには}、この町で一番の店にしたい。","en":"Since I'm opening my own shop, I want it to be the best in town."},{"form":"〜だけに","tag":"なおさら · all the more","mark":"dot","ja":"長年住んだ町{だけに}、離れるのは本当につらい。","en":"It's the town I've lived in for years, so leaving is all the harder."},{"form":"〜だけあって","tag":"さすが · lives up to it","mark":"dot","ja":"さすが料理人の息子{だけあって}、彼は包丁の使い方がうまい。","en":"As you'd expect of a chef's son, he handles a knife well."},{"form":"〜ばかりに","tag":"悪い結果 · just because","mark":"down","ja":"名前を書き忘れた{ばかりに}、テストが0点になった。","en":"Just because I forgot to write my name, I got zero on the test."},{"form":"〜あまり","tag":"〜すぎて · so much that","mark":"up","ja":"話に夢中になる{あまり}、降りる駅を通り過ぎてしまった。","en":"I was so caught up in talking that I went past my stop."},{"form":"〜のことだから","tag":"人柄から推測 · knowing X","mark":"dot","ja":"料理好きの田中さん{のことだから}、パーティーには何か作ってくるだろう。","en":"Knowing Tanaka loves cooking, she'll probably bring something she made."},{"form":"〜ことだし","tag":"理由の一つ・提案 · since…, let's","mark":"dot","ja":"宿題も終わった{ことだし}、少し散歩でもしてこよう。","en":"My homework's done, so I'll go for a little walk."}],"check":{"id":"u03d6.c1","kind":"choice","type":"文の文法1","label":"レストランで","q":"一流のシェフが作っている（　　）、この店の料理はどれもおいしい。","options":["ばかりに","だけあって","からには"],"answer":2,"why":["ばかりに leads to a result the speaker regrets. Good food is not one.","A cause, and a good result that lives up to it: praise.","からには leads to a resolve or a duty, not a description of the food."]}},"drill":[{"id":"u03d6.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"財布を^ポケットに入れたまま洗濯した^（　　）、中のカードが^全部使えなくなってしまった^。","options":["だけあって","ばかりに","だけに","あまり"],"answer":2,"why":["だけあって praises. Ruined cards are not praise.","One careless act, and a bad result the speaker regrets.","だけに needs a situation that makes a feeling stronger, as in 期待していただけに. A single careless act is not one.","あまり needs a feeling or an effort taken too far. Washing a wallet by mistake is neither."]},{"id":"u03d6.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^親友の結婚式だった^（　　）、仕事で出席できなかったのが^とても残念だ^。","options":["ばかりに","あまり","だけあって","だけに"],"answer":4,"why":["ばかりに would make the wedding the cause of missing it. Work was the cause.","あまり does not follow だった; it needs a feeling, as in 悲しさのあまり.","だけあって praises. 残念だ is not praise.","Because it was a best friend's wedding, missing it is all the more disappointing."]},{"id":"u03d6.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この公園は、^昔ここに大きな池があった^（　　）、^「大池公園」と名付けられた^。","options":["ことから","以上は","からには","だけに"],"answer":1,"why":["A fact, and a name that comes from it.","以上は leads to a duty or a firm conclusion, not to how a place got its name.","からには leads to the speaker's resolve, not to a name.","だけに makes a feeling stronger. Giving a name is not a feeling."]},{"id":"u03d6.d4","kind":"star","type":"文の文法2","label":"Build the sentence","before":"大学院に","after":"したい。","tiles":["進む","からには","世界に","通用する研究を"],"star":2,"bank":[3,1,0,2],"hint":"からには follows the plain form of a verb. What does 世界に go with?","full":"大学院に進む{からには}世界に通用する研究をしたい。","explain":"進む is the plain form before からには. 世界に goes with 通用する, and 通用する研究を is what the speaker wants to do."},{"id":"u03d6.d5","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^チームの一員である^（　　）、自分の都合だけで^練習を休むべきではない^。","options":["ばかりに","以上は","だけあって","のことだから"],"answer":2,"why":["ばかりに leads to a result the speaker regrets, not to べきではない.","Given that you are a member, there is a duty: 以上は ... べきではない.","だけあって praises a result that has happened. べきではない is advice, not praise.","のことだから follows a noun for a person, not である, and leads to a guess."]},{"id":"u03d6.d6","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^よく気がつく^田中さん（　　）、もう飲み物を用意してくれている^だろう^。","options":["ばかりに","ことだし","のことだから","からには"],"answer":3,"why":["ばかりに cannot follow a noun directly, and it leads to a regretted result, not a guess.","ことだし cannot follow a noun directly, and it leads to a suggestion, not a guess.","Someone whose character you know, then a guess with だろう.","からには cannot follow a noun directly, and it leads to a resolve, not a guess."]},{"id":"u03d6.d7","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^みんなそろった^（　　）、そろそろ^始めましょうか^。","options":["のことだから","あまり","ばかりに","ことだし"],"answer":4,"why":["のことだから follows a noun for a person (山田さんのことだから), not a verb.","あまり needs a feeling taken too far, and it cannot lead to a suggestion.","ばかりに leads to a regretted result, never to a suggestion.","One reason, then a suggestion (〜ましょうか)."]},{"id":"u03d6.d8","kind":"star","type":"文の文法2","label":"Build the sentence","before":"彼は","after":"ことに挑戦しなくなった。","tiles":["失敗を","恐れる","あまり","新しい"],"star":1,"bank":[3,2,0,1],"hint":"Which verb sits before あまり? What does 新しい describe?","full":"彼は失敗を恐れる{あまり}新しいことに挑戦しなくなった。","explain":"失敗を恐れる is the fear, in the dictionary form before あまり. 新しい describes こと."}],"exam":[{"id":"u03d6.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"本日は貸切（　　）、一般のお客様はご利用いただけません。","options":["ことから","だけに","につき","あまり"],"answer":3,"explain":"A formal notice: noun + につき. ことから would need な or である after a noun, あまり would need の, and だけに (all the more) does not fit a notice."},{"id":"u03d6.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"このホテルは百年の歴史がある（　　）、ロビーの家具も一つ一つが立派だ。","options":["だけあって","ばかりに","ことだし","からには"],"answer":1,"explain":"A cause, and praise that lives up to it: だけあって. ばかりに needs a regretted result, ことだし a suggestion, and からには a resolve or a duty."},{"id":"u03d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"マラソンに","after":"やめるわけにはいかない。","tiles":["出る","と決めた","以上は","途中で"],"star":2,"bank":[3,0,2,1],"full":"マラソンに出ると決めた{以上は}途中でやめるわけにはいかない。","explain":"出る, と決めた, 以上は, 途中で. 以上は follows the plain form 決めた, and 途中で goes with やめる."}]},"scene":{"ja":"市立図書館で","en":"At the city library","intro":"Tap every word you would read at the counter and on the notices.","words":[{"id":"lend","word":"貸出","reading":"かしだし","gloss":"lending, check-out","parts":[["貸","かし","lend"],["出","だし","out"]],"clip":"s_u3d6_lend"},{"id":"return","word":"返却","reading":"へんきゃく","gloss":"return (of something borrowed)","parts":[["返","ヘン","give back"],["却","キャク","back, away"]],"clip":"s_u3d6_return"},{"id":"user","word":"利用者","reading":"りようしゃ","gloss":"user","parts":[["利用","りよう","use"],["者","シャ","person: 学者"]],"clip":"s_u3d6_user"},{"id":"view","word":"閲覧","reading":"えつらん","gloss":"reading, viewing (on site)","parts":[["閲","エツ","look over"],["覧","ラン","look at: 一覧"]],"clip":"s_u3d6_view"},{"id":"register","word":"登録","reading":"とうろく","gloss":"registration","parts":[["登","トウ","put on a list"],["録","ロク","record: 記録"]],"clip":"s_u3d6_register"},{"id":"count","word":"冊数","reading":"さっすう","gloss":"number of books","parts":[["冊","サツ","counter for books"],["数","スウ","number"]],"clip":"s_u3d6_count"},{"id":"new","word":"新着","reading":"しんちゃく","gloss":"new arrivals","parts":[["新","シン","new"],["着","チャク","arrive: 到着"]],"clip":"s_u3d6_new"},{"id":"food","word":"飲食","reading":"いんしょく","gloss":"eating and drinking","parts":[["飲","イン","drink"],["食","ショク","eat"]],"clip":"s_u3d6_food"}],"check":{"id":"u03d6.k1","kind":"choice","type":"表記","label":"How the exam asks it","q":"借りた本は、一階のカウンターに_へんきゃく_してください。","options":["変却","返脚","返却","反却"],"answer":3,"explain":"返 is \"give back\", as in 返事 and 返す, and 却 is キャク: 返却. 変 means \"change\", 反 means \"against\", and 脚 (キャク) means \"leg\"."}},"skill":{"kind":"reading","ja":"主張","en":"The writer's main point","ask":"What is the writer's main point?","seconds":100,"passage":"最近、駅前の図書館が夜九時まで開くようになった。仕事帰りに寄れることから、会社員の利用者が増えているという。私も週に一度は通っている。^ただ^、残念なのは、借りた本を期限が過ぎても返さない人が少なくないことだ。人気のある本ほど予約が多いだけに、一人が遅れると何人もが待たされることになる。図書館はみんなのお金で運営されている。公共の物を借りる以上、決められた日までに返すのは^当然ではないだろうか^。一人一人がその意識を持つことが、図書館をもっと使いやすくする^いちばんの近道だと思う^。","strategy":"The opening is background. Look after ただ, and at the sentences that end in 〜ではないだろうか and 〜と思う.","item":{"id":"u03d6.r1","kind":"choice","type":"読解・主張","q":"筆者がいちばん言いたいことは何か。","options":["図書館は、もっと遅くまで開くべきだ。","借りた本は、決められた日までに返すべきだ。","人気のある本は、予約しないと借りられない。","図書館の利用者を、もっと増やすべきだ。"],"short":["もっと遅くまで開くべき","決められた日までに返すべき","人気の本は予約が必要","利用者を増やすべき"],"answer":2,"explain":"After ただ, the writer turns to a problem: books returned late. The view is given with 〜当然ではないだろうか and repeated at the end with その意識 and 〜と思う.","why":["Option 1 is background. The library already opens until nine, and the writer does not ask for more.","","Option 3 is not said. The text says popular books have many reservations, not that you must reserve them.","Option 4 is background. The writer reports that users have increased but does not argue for more."]}}}],"test":[{"id":"u03t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"来月でアパートの_契約_が切れる。","options":["けやく","げいやく","けいやく","けいやっく"],"answer":3,"explain":"契約 is けいやく: 契 is ケイ with a long vowel, and 約 is ヤク as in 約束. けやく shortens the vowel, げいやく adds voicing, and けいやっく adds a small っ."},{"id":"u03t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"四月から、このバスの_運賃_が上がる。","options":["うんちん","うんじん","うちん","うんしん"],"answer":1,"explain":"運賃 is うんちん: 運 is ウン, and 賃 is チン as in 家賃. うんじん adds voicing, うちん drops the ん, and うんしん misreads 賃."},{"id":"u03t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"この書類の下の欄に、_しょめい_をお願いします。","options":["暑名","署名","緒名","諸名"],"answer":2,"explain":"A signature is 署名. 暑, 緒 and 諸 share the part 者 and look alike, but 暑名, 緒名 and 諸名 are not words."},{"id":"u03t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"_しんせいしょ_に必要なことを記入して、窓口に出してください。","options":["申精書","伸請書","申清書","申請書"],"answer":4,"explain":"An application form is 申請書: 申 \"say\" and 請 \"request\". 精 and 清 sound like セイ but do not make this word, and 伸 is \"stretch\", not 申."},{"id":"u03t.5","kind":"choice","type":"語形成","label":"Word formation","q":"銀行の窓口で振り込むと、手数（　　）が三百円かかる。","options":["料","費","代","賃"],"answer":1,"explain":"A handling fee is 手数料. 料 makes many fees (送料, 入場料). 手数費, 手数代 and 手数賃 are not words."},{"id":"u03t.6","kind":"choice","type":"語形成","label":"Word formation","q":"（　　）記入の欄がある申請書は、受け付けられません。","options":["不","非","未","反"],"answer":3,"explain":"未 means \"not yet\": 未記入 is a box not yet filled in. 不記入, 非記入 and 反記入 are not words."},{"id":"u03t.7","kind":"choice","type":"文脈規定","label":"Word in context","q":"大雪のため、この路線は午後から（　　）となった。","options":["休業","運休","休講","欠勤"],"answer":2,"explain":"A train line that stops running is 運休. 休業 is a shop or business closing, 休講 is a cancelled class, and 欠勤 is a worker staying off work."},{"id":"u03t.8","kind":"choice","type":"文脈規定","label":"Word in context","q":"このアパートは、二年ごとに契約を（　　）する決まりになっている。","options":["署名","記入","発行","更新"],"answer":4,"explain":"A contract is renewed: 契約を更新する. You sign a document (書類に署名する), fill in a form (用紙に記入する) and a certificate is issued (発行する), but none of these takes 契約を."},{"id":"u03t.9","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この町は、昔から焼き物作りが盛んである（　　）、「焼き物の町」として知られている。","options":["につき","ことから","からには","ばかりに"],"answer":2,"explain":"A fact gives the grounds for a name or reputation (〜として知られている): ことから. につき follows a noun on a notice, からには needs a resolve or duty after it, and ばかりに needs a result the speaker regrets."},{"id":"u03t.10","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ただいま準備中（　　）、もうしばらくお待ちください。","options":["あまり","だけあって","につき","のことだから"],"answer":3,"explain":"A noun + につき gives the reason on a notice, and a polite request can follow. あまり needs a feeling noun with の, だけあって praises a result, and のことだから needs a person and a guess."},{"id":"u03t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"一度引き受けた（　　）、途中で投げ出すわけにはいかない。","options":["わりに","あまり","だけあって","以上"],"answer":4,"explain":"Having taken the job on is a fact that brings a duty, and わけにはいかない states it: 以上. わりに sets up a contrast, あまり needs a feeling taken too far, and だけあって praises a result that has come about."},{"id":"u03t.12","kind":"choice","type":"文の文法1","label":"Choose the form","q":"大学院に進む（　　）、研究者として認められるような成果を出したい。","options":["からには","ばかりに","あまり","ことから"],"answer":1,"explain":"Going on to graduate school commits the speaker, and a strong wish follows: からには. ばかりに needs a regretted result, あまり a feeling taken too far, and ことから gives grounds for a judgement, not a wish."},{"id":"u03t.13","kind":"choice","type":"文の文法1","label":"Choose the form","q":"さすがプロの料理人（　　）、包丁の使い方が私たちとはまったく違う。","options":["にしては","ばかりに","だけあって","ことだし"],"answer":3,"explain":"さすが with a status, and skill that lives up to it: だけあって, which can follow a noun directly. にしては says the result falls short of what you expect, which clashes with さすが. ばかりに and ことだし would need である after a noun, and neither praises."},{"id":"u03t.14","kind":"choice","type":"文の文法1","label":"Choose the form","q":"苦労してやっと手に入れたチケット（　　）、なくしたときのショックは大きかった。","options":["だけあって","だけに","からには","ことだし"],"answer":2,"explain":"The harder it was to get, the bigger the shock: だけに, which can follow a noun directly. だけあって praises, and a shock is not praise. からには and ことだし would need である after a noun, and they lead to a resolve or a suggestion, not a feeling."},{"id":"u03t.15","kind":"choice","type":"文の文法1","label":"Choose the form","q":"私が余計なことを言った（　　）、二人はけんかになってしまった。","options":["だけあって","からには","あまり","ばかりに"],"answer":4,"explain":"One careless remark, and a bad result the speaker regrets (〜てしまった): ばかりに. だけあって praises, からには needs a resolve or duty after it, and あまり needs a feeling or effort taken too far, which one remark is not."},{"id":"u03t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"試験に","after":"泣き出してしまった。","tiles":["合格した","うれしさの","あまり","思わず"],"star":2,"bank":[3,1,0,2],"full":"試験に合格したうれしさの{あまり}思わず泣き出してしまった。","explain":"合格した, うれしさの, あまり, 思わず. 試験に needs its verb 合格した, which describes うれしさ. The feeling noun takes の before あまり, and 思わず goes with the result 泣き出してしまった."},{"id":"u03t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あの","after":"このケーキもすぐに食べてしまうだろう。","tiles":["甘いものに","目がない","母の","ことだから"],"star":1,"bank":[2,3,0,1],"full":"あの甘いものに{目がない}母のことだからこのケーキもすぐに食べてしまうだろう。","explain":"甘いものに, 目がない, 母の, ことだから. 甘いものに目がない (loves sweets) describes 母, the person takes の before ことだから, and a guess with だろう follows."},{"id":"u03t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"メンバーも全員","after":"ましょうか。","tiles":["そろった","ことだし","会議を","始め"],"star":2,"bank":[2,0,3,1],"full":"メンバーも全員そろったことだし{会議を}始めましょうか。","explain":"そろった, ことだし, 会議を, 始め. 全員そろった is the reason in the plain form before ことだし, and the suggestion 会議を始めましょうか follows. 始め must sit right before ましょうか."},{"id":"u03t.19","kind":"choice","type":"読解・内容理解","label":"Short passage","q":"図書館が休館するのはなぜか。","options":["返却ポストを新しくするため","本を整理するため","空調設備の工事をするため","CDやDVDのケースを直すため"],"answer":3,"passage":"館内の空調設備工事につき、7月10日から7月23日まで臨時休館いたします。休館中に本を返却される方は、正面入口横の返却ポストをご利用ください。ただし、CDやDVDはケースが割れるおそれがあるため、ポストには入れず、開館後にカウンターへお返しください。なお、予約された本の受け取り期限は、休館した日数の分だけ延長いたします。ご不便をおかけしますが、ご理解をお願いいたします。","short":["ポストを新しくする","本を整理する","空調の工事","ケースを直す"],"explain":"The first sentence gives the reason with につき: 空調設備工事につき. The post box, sorting books and repairing cases are not given as reasons; cases are mentioned only as a risk in the post box."},{"id":"u03t.20","kind":"choice","type":"読解・内容理解","label":"Short passage","q":"休館中にDVDを返したい人は、どうすればいいか。","options":["正面入口横の返却ポストに入れる","開館してからカウンターに返す","休館中にカウンターに持っていく","受け取り期限の延長を申し込む"],"answer":2,"passage":"館内の空調設備工事につき、7月10日から7月23日まで臨時休館いたします。休館中に本を返却される方は、正面入口横の返却ポストをご利用ください。ただし、CDやDVDはケースが割れるおそれがあるため、ポストには入れず、開館後にカウンターへお返しください。なお、予約された本の受け取り期限は、休館した日数の分だけ延長いたします。ご不便をおかけしますが、ご理解をお願いいたします。","short":["ポストに入れる","開館後カウンターへ","休館中にカウンターへ","延長を申し込む"],"explain":"ただし says DVDs must not go in the post box but be returned to the counter after the library reopens. The post box is for books only, the counter is closed during the closure, and the extended deadline is for reserved books and needs no request."},{"id":"u03t.21","kind":"choice","type":"読解・内容理解","label":"Short passage","q":"初日に長い行列ができていたのはなぜか。","options":["パンの値段が安かったから","駅前で便利な場所にあったから","朝早くから開いていたから","テレビで何度も紹介されていたから"],"answer":4,"passage":"先日、駅前に新しいパン屋ができた。開店前からテレビで何度も紹介されていただけに、初日は朝から長い行列ができていた。私も一時間並んで、いちばん人気だというクロワッサンを買ってみた。ところが、食べてみると、近所のスーパーで売っているものとそれほど変わらない。期待が大きかった分、少しがっかりしてしまった。もちろん、味の好みは人それぞれだ。ただ、これからは評判だけで店を選ぶのはやめようと思った。","short":["安かった","駅前で便利","朝早く開いた","テレビで紹介された"],"explain":"〜ていただけに links the TV coverage to the long queue on day one. The price is never mentioned, and the station and the morning are only where and when, not the reason."},{"id":"u03t.22","kind":"choice","type":"読解・内容理解","label":"Short passage","q":"この経験から、筆者はどう考えたか。","options":["評判だけで店を選ばないようにしよう","人気の店には並ぶ価値がある","スーパーのパンのほうがおいしい","味の好みはだれでも同じだ"],"answer":1,"passage":"先日、駅前に新しいパン屋ができた。開店前からテレビで何度も紹介されていただけに、初日は朝から長い行列ができていた。私も一時間並んで、いちばん人気だというクロワッサンを買ってみた。ところが、食べてみると、近所のスーパーで売っているものとそれほど変わらない。期待が大きかった分、少しがっかりしてしまった。もちろん、味の好みは人それぞれだ。ただ、これからは評判だけで店を選ぶのはやめようと思った。","short":["評判だけで選ばない","並ぶ価値がある","スーパーのほうがおいしい","好みはだれでも同じ"],"explain":"The last sentence says the writer will stop choosing shops by reputation alone. The writer found the queue not worth it, said the bread was about the same as the supermarket's (not worse), and said tastes differ from person to person."},{"id":"u03t.23","kind":"choice","type":"読解・内容理解","label":"Short passage","q":"筆者が発表を引き受けたのはなぜか。","options":["英語で話すのが得意だから","木村さんに頼まれたから","部長に大丈夫だと言われたから","海外の展示会に行きたかったから"],"answer":3,"passage":"来月、会社の代表として海外の展示会で発表することになった。英語で話すのは苦手なので、最初は断ろうかと思った。しかし、部長に「君なら大丈夫だ」と言われ、引き受けることにした。引き受けたからには、言い訳はできない。今は毎朝三十分早く起きて、発表の練習をしている。それを聞いた同僚の木村さんは、「心配性の君のことだから、準備しすぎて疲れないようにね」と笑っていた。確かに、そうかもしれない。","short":["英語が得意","木村さんに頼まれた","部長に大丈夫と言われた","展示会に行きたかった"],"explain":"しかし、部長に「君なら大丈夫だ」と言われ、引き受けることにした gives the reason. The writer says English is a weak point, Kimura-san only comments afterwards, and nothing is said about wanting to go abroad."},{"id":"u03t.24","kind":"choice","type":"読解・内容理解","label":"Short passage","q":"木村さんは筆者についてどう思っているか。","options":["発表を断ったほうがよかった","英語の練習が足りない","朝早く起きるのが苦手だ","準備をしすぎるかもしれない"],"answer":4,"passage":"来月、会社の代表として海外の展示会で発表することになった。英語で話すのは苦手なので、最初は断ろうかと思った。しかし、部長に「君なら大丈夫だ」と言われ、引き受けることにした。引き受けたからには、言い訳はできない。今は毎朝三十分早く起きて、発表の練習をしている。それを聞いた同僚の木村さんは、「心配性の君のことだから、準備しすぎて疲れないようにね」と笑っていた。確かに、そうかもしれない。","short":["断ったほうがよかった","練習が足りない","早起きが苦手","準備をしすぎる"],"explain":"心配性の君のことだから shows Kimura-san knows the writer is a worrier and guesses they may over-prepare and tire themselves. Kimura-san says nothing about refusing, about too little practice, or about getting up early being hard."}]},{"n":4,"ja":"条件・仮定","en":"Conditions","days":[{"title":"〜としたら・〜とすれば"},{"title":"〜ないことには・〜ない限り"},{"title":"〜さえ〜ば・〜次第で"},{"title":"〜ものなら・〜ようものなら"},{"title":"〜を抜きにしては・〜なしには"},{"title":"まとめ：似ている文法"}],"test":[]},{"n":5,"ja":"逆接・譲歩","en":"Contrast and concession","days":[{"title":"〜ものの・〜とはいえ"},{"title":"〜くせに・〜にもかかわらず"},{"title":"〜たところで・〜としても"},{"title":"〜からといって・〜わけではない"},{"title":"〜ながらも・〜つつも"},{"title":"まとめ：似ている文法"}],"test":[]},{"n":6,"ja":"比較・程度","en":"Comparison and degree","days":[{"title":"〜ほど〜はない・〜に越したことはない"},{"title":"〜くらいなら・〜よりほかない"},{"title":"〜に比べて・〜に反して"},{"title":"〜ば〜ほど・〜につれて"},{"title":"〜というより・〜どころか"},{"title":"まとめ：似ている文法"}],"test":[]},{"n":7,"ja":"変化・傾向","en":"Change and tendency","days":[{"title":"〜がちだ・〜気味だ"},{"title":"〜っぽい・〜げ"},{"title":"〜おそれがある・〜かねない"},{"title":"〜に伴って・〜とともに"},{"title":"〜つつある・〜一方だ"},{"title":"まとめ：似ている文法"}],"test":[]},{"n":8,"ja":"判断・主張","en":"Judgement and stance","days":[{"title":"〜わけがない・〜わけにはいかない"},{"title":"〜ざるを得ない・〜ほかない"},{"title":"〜べきだ・〜べきではない"},{"title":"〜ことはない・〜までもない"},{"title":"〜に違いない・〜に相違ない"},{"title":"まとめ：似ている文法"}],"test":[]},{"n":9,"ja":"対象・関連","en":"Topic and relation","days":[{"title":"〜に対して・〜について"},{"title":"〜に関して・〜をめぐって"},{"title":"〜にとって・〜としては"},{"title":"〜に応じて・〜に沿って"},{"title":"〜に基づいて・〜をもとに"},{"title":"まとめ：似ている文法"}],"test":[]},{"n":10,"ja":"立場・評価","en":"Viewpoint and evaluation","days":[{"title":"〜からすると・〜から見ると"},{"title":"〜にしては・〜わりに"},{"title":"〜として・〜にしても"},{"title":"〜にしろ・〜にせよ"},{"title":"〜はともかく・〜はさておき"},{"title":"まとめ：似ている文法"}],"test":[]},{"n":11,"ja":"気持ち・強調","en":"Feelings and emphasis","days":[{"title":"〜てたまらない・〜てならない"},{"title":"〜ずにはいられない・〜ないではいられない"},{"title":"〜ものだ・〜ものか"},{"title":"〜ことか・〜ことだ"},{"title":"〜てしょうがない・〜てしかたがない"},{"title":"まとめ：似ている文法"}],"test":[]},{"n":12,"ja":"話題・伝聞・手順","en":"Topic, hearsay and sequence","days":[{"title":"〜というと・〜といえば"},{"title":"〜ということだ・〜とのことだ"},{"title":"〜上で・〜上は"},{"title":"〜ついでに・〜がてら"},{"title":"〜うえに・〜ばかりでなく"},{"title":"まとめ：似ている文法"}],"test":[]}],"items":{"u03d1.c1":{"id":"u03d1.c1","kind":"choice","type":"文の文法1","label":"イベントのお知らせ","q":"当日は混雑が予想される（　　）、お早めにお越しください。","options":["ことから","につき","ため"],"answer":3,"why":["ことから backs a judgement or a name. A request like お越しください cannot follow it.","につき follows a noun, not a verb clause like 予想される.","ため follows a plain verb and can lead to a request on a notice."],"unit":3,"day":1,"step":"compare"},"u03d1.d1":{"id":"u03d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"朝、道がぬれていた（　　）、^夜のうちに雨が降ったと分かった^。","options":["につき","ばかりに","ことから","あまり"],"answer":3,"why":["につき follows a noun and belongs on notices, not in a judgement like this.","ばかりに needs a result the speaker regrets. Finding something out is not one.","The wet road is the grounds, and 雨が降ったと分かった is the conclusion.","あまり is for a feeling or effort taken too far. A wet road is neither."],"unit":3,"day":1,"step":"drill"},"u03d1.d2":{"id":"u03d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^本日は定休日^（　　）、営業しておりません。","options":["ことから","につき","あまり","からには"],"answer":2,"why":["After a noun, ことから needs である (定休日であることから), and it backs a judgement, not a shop notice.","A noun + につき: the formal reason on a notice.","あまり is for a feeling taken too far. 定休日 is not a feeling.","からには needs である after a noun, and a decision or duty after it."],"unit":3,"day":1,"step":"drill"},"u03d1.d3":{"id":"u03d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この橋は、近くに大きな松の木がある（　　）、「松橋」と^呼ばれている^。","options":["ことから","につき","ばかりに","あまり"],"answer":1,"why":["The grounds for a name: 〜ことから〜と呼ばれている.","につき follows a noun, not a clause like 木がある.","ばかりに needs a result the speaker regrets. A name is not one.","あまり is for a feeling taken too far. A tree near a bridge is not one."],"unit":3,"day":1,"step":"drill"},"u03d1.d4":{"id":"u03d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ただいま^館内工事中^（　　）、エレベーターは使用できません。","options":["のにつき","なことから","につき","のあまり"],"answer":3,"why":["No の here: につき follows the noun 工事中 directly.","工事中 is a noun, so 〜な does not attach to it. It would need である.","A noun + につき: the formal reason on a notice.","あまり is for a feeling taken too far. Construction work is not a feeling."],"unit":3,"day":1,"step":"drill"},"u03d1.d5":{"id":"u03d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"窓ガラスが","after":"と考えられる。","tiles":["割れていた","ことから","犯人は","外から入った"],"star":2,"bank":[2,0,3,1],"hint":"Which tile can follow 窓ガラスが? The conclusion comes last, right before と考えられる.","full":"窓ガラスが割れていた{ことから}犯人は外から入ったと考えられる。","explain":"割れていた follows 窓ガラスが, and ことから follows the plain form. Then the conclusion: 犯人は, and 外から入った right before と考えられる.","unit":3,"day":1,"step":"drill"},"u03d1.d6":{"id":"u03d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"台風","after":"とさせていただきます。","tiles":["接近","につき","本日の営業は","午後3時まで"],"star":2,"bank":[3,1,2,0],"hint":"につき follows a noun. Which tile is the noun that goes with 台風?","full":"台風接近{につき}本日の営業は午後3時までとさせていただきます。","explain":"台風接近 is one noun, and につき follows it. 本日の営業は is the topic, and 午後3時まで sits right before とさせていただきます.","unit":3,"day":1,"step":"drill"},"u03d1.e1":{"id":"u03d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"彼は関西の言葉を話す（　　）、大阪の出身ではないかと思った。","options":["につき","ことから","からには","あまり"],"answer":2,"explain":"The way he speaks is the grounds for a guess, so ことから. につき follows a noun on a notice, からには needs a decision or duty after it, and あまり needs a feeling taken too far.","unit":3,"day":1,"step":"exam"},"u03d1.e2":{"id":"u03d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この先、道路工事（　　）、車両は通行止めとなっております。","options":["ことから","にとって","につき","ばかりに"],"answer":3,"explain":"A noun + につき gives the reason on a notice. ことから and ばかりに would need である after a noun, and にとって gives a point of view, not a reason.","unit":3,"day":1,"step":"exam"},"u03d1.e3":{"id":"u03d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"この島は、","after":"「かめ島」と呼ばれている。","tiles":["上から見ると","かめの","形をしている","ことから"],"star":2,"bank":[3,2,0,1],"full":"この島は、上から見るとかめの{形をしている}ことから「かめ島」と呼ばれている。","explain":"上から見ると, かめの, 形をしている, ことから. かめの describes 形, and ことから gives the grounds for the name, so it sits right before 「かめ島」.","unit":3,"day":1,"step":"exam"},"u03d1.k1":{"id":"u03d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"店内_改装_のため、来週まで休業いたします。","options":["かいしょう","かいぞう","かいそう","こうそう"],"answer":3,"explain":"装 is ソウ here, as in 服装. かいぞう is a different word (改造, rebuilding), かいしょう is not this word, and 改 is never read こう.","unit":3,"day":1,"step":"scene"},"u03d1.r1":{"id":"u03d1.r1","kind":"choice","type":"即時応答","label":"Quick response","q":"男：すみません、この入口、「工事中につき使用できません」って書いてあるんですけど……。","script":["男：すみません、この入口、「工事中につき使用できません」って書いてあるんですけど……。","女：はい、こちらの入口からどうぞ。","女：申し訳ございません。お手数ですが、裏の入口をご利用ください。","女：工事はいつ始まるんですか。"],"options":["はい、こちらの入口からどうぞ。","申し訳ございません。お手数ですが、裏の入口をご利用ください。","工事はいつ始まるんですか。"],"short":["こちらの入口からどうぞ","裏の入口をご利用ください","工事はいつ始まる？"],"answer":2,"why":["The notice says this entrance cannot be used, so she cannot invite him through it.","She apologises and sends him to another entrance, as the notice requires.","The notice says 工事中: the work has already started, and he is the one asking."],"unit":3,"day":1,"step":"skill","clip":"l_u3d1"},"u03d2.c1":{"id":"u03d2.c1","kind":"choice","type":"文の文法1","label":"山の名前","q":"形が富士山に似ている（　　）、この山は「北の富士」と呼ばれている。","options":["以上は","からには","ことから"],"answer":3,"why":["以上は leads to a duty, a resolve or a judgement. A name people use is none of these.","からには needs a resolve or a duty after it, and a name is neither.","ことから gives the grounds for a name: 〜ことから「…」と呼ばれている."],"unit":3,"day":2,"step":"compare"},"u03d2.d1":{"id":"u03d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"契約書に署名する（　　）、^内容をよく理解しておくべきだ^。","options":["以上は","おかげで","ことから","わりに"],"answer":1,"why":["If you are going to sign, then you should understand it: a duty follows 以上は.","おかげで thanks a cause for a good result. A duty does not follow it.","ことから gives grounds taken from a known fact. Signing has not happened yet.","わりに contrasts: \"for something that …\". There is no contrast here."],"unit":3,"day":2,"step":"drill"},"u03d2.d2":{"id":"u03d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"自分で^やると決めた^（　　）、^途中で投げ出すわけにはいかない^。","options":["おかげで","からには","ものの","ことから"],"answer":2,"why":["おかげで needs a good result after it, not a duty.","A decision that commits you, then \"I can't give up\": a resolve follows からには.","ものの means \"although\", and nothing here goes against the decision.","ことから gives grounds for a judgement about facts, not a personal duty like this."],"unit":3,"day":2,"step":"drill"},"u03d2.d3":{"id":"u03d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^プロである^（　　）、^結果で評価されるのは当然だ^。","options":["わりに","以上","ものの","おかげで"],"answer":2,"why":["わりに sets up a surprise, and 当然だ says there is none.","Noun + である + 以上, then a judgement: 当然だ.","ものの means \"although\", but being a pro and being judged on results go together.","おかげで needs a good result after it. 当然だ is a judgement, not a result."],"unit":3,"day":2,"step":"drill"},"u03d2.d4":{"id":"u03d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^日本で働く^（　　）、敬語くらいはきちんと^使えるようになりたい^。","options":["ものの","ことから","からには","わりに"],"answer":3,"why":["ものの means \"although\", and the wish does not go against working in Japan.","ことから does not lead to a wish like 〜たい.","A commitment (working in Japan), then a strong wish: からには.","わりに contrasts, and a wish does not contrast with working in Japan."],"unit":3,"day":2,"step":"drill"},"u03d2.d5":{"id":"u03d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"一度仕事を","after":"通すべきだ。","tiles":["引き受けた","以上は","最後まで","やり"],"star":2,"bank":[3,0,2,1],"hint":"What does 仕事を need right after it? やり must sit right before 通す.","full":"一度仕事を引き受けた{以上は}最後までやり通すべきだ。","explain":"仕事を takes the verb 引き受けた, and 以上は follows it. やり joins 通す to make やり通す, so 最後まで comes just before やり.","unit":3,"day":2,"step":"drill"},"u03d2.d6":{"id":"u03d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"試験を","after":"したい。","tiles":["受ける","からには","一回で","合格"],"star":1,"bank":[2,3,1,0],"hint":"試験を needs its verb first. Which noun goes with したい?","full":"試験を受ける{からには}一回で合格したい。","explain":"試験を受ける, then からには after the plain form. 合格 joins したい, and 一回で says how: 一回で合格したい.","unit":3,"day":2,"step":"drill"},"u03d2.e1":{"id":"u03d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"会社の代表として出席する（　　）、個人的な意見を言うわけにはいかない。","options":["ものの","以上は","わりに","につき"],"answer":2,"explain":"Attending as the company's representative is a fact that brings a duty: 以上は. ものの and わりに set up a contrast that is not here, and につき follows a noun, not a verb.","unit":3,"day":2,"step":"exam"},"u03d2.e2":{"id":"u03d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ここまで来た（　　）、もう後には引けない。","options":["おかげで","ものの","からには","ことから"],"answer":3,"explain":"Having come this far commits the speaker, and a resolve follows: からには. おかげで needs a good result, ものの means \"although\", and ことから gives grounds for a judgement, not a resolve.","unit":3,"day":2,"step":"exam"},"u03d2.e3":{"id":"u03d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"親に","after":"ばかりはいられない。","tiles":["学費を","出してもらっている","以上","遊んで"],"star":2,"bank":[3,2,0,1],"full":"親に学費を出してもらっている{以上}遊んでばかりはいられない。","explain":"学費を, 出してもらっている, 以上, 遊んで. 以上 follows the verb, and 遊んで must sit right before ばかりはいられない.","unit":3,"day":2,"step":"exam"},"u03d2.k1":{"id":"u03d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"書類の提出_期限_は三月十日です。","options":["きげん","きかん","ごげん","きけん"],"answer":1,"explain":"期限 is きげん: 期 is キ as in 期間, and 限 is ゲン as in 制限. きかん is 期間 (a period), きけん is 危険 (danger), and ごげん is not a reading of 期限.","unit":3,"day":2,"step":"scene"},"u03d2.r1":{"id":"u03d2.r1","kind":"choice","type":"読解・理由","q":"筆者が契約書を最後まで読むようになったのはなぜか。","options":["細かい字で書かれた条件は、どれも同じだとわかったから。","署名した以上、知らなかったでは済まないとわかったから。","部屋を貸す会社に、最後まで読むように言われたから。","解約の費用は払わなくてもいいと知ったから。"],"short":["条件はどれも同じ","知らなかったでは済まない","会社に言われた","解約の費用は払わなくていい"],"answer":2,"explain":"After それ以来 the writer states the new habit, and the next sentence gives its reason with 〜からだ.","why":["Option 1 is the writer's old view, the reason they used to skip the conditions.","","Option 3 is not in the text. Nobody told the writer to read contracts.","Option 4 is the opposite. The writer had to pay an unexpected cost."],"unit":3,"day":2,"step":"skill"},"u03d3.c1":{"id":"u03d3.c1","kind":"choice","type":"文の文法1","label":"コンサートの日","q":"ずっと楽しみにしていた（　　）、コンサートが中止になって本当に残念だ。","options":["ばかりに","だけあって","だけに"],"answer":3,"why":["ばかりに says the cause brought about the bad result. Looking forward to it did not cause the cancellation.","だけあって praises a result that lives up to the cause. A cancellation is not praise.","Because she had looked forward to it, the disappointment is all the more."],"unit":3,"day":3,"step":"compare"},"u03d3.d1":{"id":"u03d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^さすが^一流ホテル（　　）、^サービスがすばらしい^。","options":["ばかりに","あまり","だけあって","からには"],"answer":3,"why":["ばかりに needs a bad result the speaker regrets, and it does not follow a noun directly.","あまり follows a feeling noun with の, as in 心配のあまり. 一流ホテル is not a feeling.","さすが with a status, and a result that lives up to it: praise.","からには needs a decision or duty after it, and 一流ホテル would need である before it."],"unit":3,"day":3,"step":"drill"},"u03d3.d2":{"id":"u03d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^期待が大きかった^（　　）、負けたときの^ショックも大きかった^。","options":["からには","だけあって","わりに","だけに"],"answer":4,"why":["からには needs a decision or duty after it, not a feeling that has already happened.","だけあって praises. A painful shock is not a result anyone praises.","わりに sets up a contrast, but a big hope and a big shock go together.","The bigger the hope, the bigger the shock: も marks the \"all the more\"."],"unit":3,"day":3,"step":"drill"},"u03d3.d3":{"id":"u03d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^毎日五時間も練習している^（　　）、彼女の演奏は^見事だった^。","options":["ばかりに","だけあって","あまり","ものの"],"answer":2,"why":["ばかりに leads to a bad result. 見事だった is praise.","Hard practice, and a performance that lives up to it.","あまり is \"too much, so something went wrong\". Here nothing went wrong.","ものの means \"although\", but the practice and the fine performance do not contrast."],"unit":3,"day":3,"step":"drill"},"u03d3.d4":{"id":"u03d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^ふだんおとなしい^彼（　　）、急に大声を出したときは^みんな驚いた^。","options":["だけに","だけあって","ばかりに","からには"],"answer":1,"why":["Because he is usually so quiet, the shout was all the more surprising.","だけあって means the result is what you would expect. Here everyone was surprised.","ばかりに does not follow a noun directly, and his being quiet did not cause the shout.","からには does not follow a noun directly, and it needs a decision or duty after it."],"unit":3,"day":3,"step":"drill"},"u03d3.d5":{"id":"u03d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"初めての海外旅行","after":"新鮮に感じられた。","tiles":["だった","だけに","見るもの","すべてが"],"star":2,"bank":[2,1,3,0],"hint":"だけに follows a plain form here. Which tile turns 旅行 into one?","full":"初めての海外旅行だった{だけに}見るものすべてが新鮮に感じられた。","explain":"旅行だった is the plain past, so だけに comes right after it. 見るものすべてが is \"everything I saw\", and it is the subject of 新鮮に感じられた.","unit":3,"day":3,"step":"drill"},"u03d3.d6":{"id":"u03d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"さすが","after":"できていた。","tiles":["人気の","店","だけあって","行列が"],"star":1,"bank":[3,2,0,1],"hint":"だけあって can follow a noun directly. Which noun is さすが about?","full":"さすが人気の{店}だけあって行列ができていた。","explain":"人気の describes 店, and 店 takes だけあって directly. 行列が goes with できていた.","unit":3,"day":3,"step":"drill"},"u03d3.e1":{"id":"u03d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"このかばんは有名なブランドの製品（　　）、十年使っても少しも傷んでいない。","options":["だけあって","ばかりに","にしては","あまり"],"answer":1,"explain":"A famous brand, and a bag that lives up to it: だけあって, which can follow a noun directly. ばかりに needs a bad result, にしては sets up a contrast with what you would expect, and あまり needs a feeling noun with の.","unit":3,"day":3,"step":"exam"},"u03d3.e2":{"id":"u03d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"彼女は小さいころからずっと努力してきた（　　）、今回の不合格はとても悔しいだろう。","options":["だけあって","だけに","ばかりに","くせに"],"answer":2,"explain":"Years of effort make the failure all the more painful: だけに. だけあって needs a good result, ばかりに needs a cause that brought the result about, and くせに criticises someone.","unit":3,"day":3,"step":"exam"},"u03d3.e3":{"id":"u03d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"ベテランの","after":"みんな驚いた。","tiles":["山田さん","だけに","今回の","ミスには"],"star":2,"bank":[3,0,2,1],"full":"ベテランの山田さんだけに{今回の}ミスにはみんな驚いた。","explain":"山田さん, だけに, 今回の, ミスには. ベテランの describes 山田さん, だけに follows the noun directly, and 今回の must sit right before ミスには.","unit":3,"day":3,"step":"exam"},"u03d3.k1":{"id":"u03d3.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"名前を呼ばれるまで、_待合室_でお待ちください。","options":["まちあいしつ","まちごうしつ","たいごうしつ","まちあいじつ"],"answer":1,"explain":"待合室 is まちあいしつ: 待ち合い (kun) + 室 (しつ). 合 is not read ごう here, 待 is not read たい, and 室 does not become じつ.","unit":3,"day":3,"step":"scene"},"u03d3.r1":{"id":"u03d3.r1","kind":"choice","type":"ポイント理解","q":"女の人はどうしてこの病院に通うことにしましたか。","script":["ナレーター：病院の待合室で、男の人と女の人が話しています。女の人はどうしてこの病院に通うことにしましたか。","男：あれ、田中さん。この病院に来てるんですか。","女：ええ、先月から。前は駅前の内科に通ってたんですけど。","男：駅前のほうが近いのに。先生が合わなかったんですか。","女：いえ、先生はとても親切でしたよ。ただ、予約ができなくて、いつも一時間以上待たされたんです。","男：ここは建物も新しくて、きれいですよね。","女：ええ。でも、決めたのはネットで予約できるからなんです。おかげで、待ち時間がほとんどなくて。","男：なるほど。少し遠くても、そのほうが楽ですね。","ナレーター：女の人はどうしてこの病院に通うことにしましたか。"],"options":["駅前の内科の先生が親切ではなかったから","予約ができて、待ち時間が短いから","建物が新しくて、きれいだから","家から近くて、通いやすいから"],"printed":true,"short":["先生が親切ではなかった","予約ができて待たない","建物が新しくてきれい","家から近い"],"answer":2,"why":["She says the doctor there was very kind.","決めたのは…からなんです gives her reason: online booking, and almost no waiting.","She agrees the building is nice, then says でも: that is not why she chose it.","The station clinic is the closer one. This one is a little far (少し遠くても)."],"unit":3,"day":3,"step":"skill","clip":"l_u3d3"},"u03d4.c1":{"id":"u03d4.c1","kind":"choice","type":"文の文法1","label":"合格発表の日","q":"うれしさの（　　）、思わず大声を出した。","options":["ばかりに","あまり","だけに"],"answer":2,"why":["ばかりに cannot follow の, and nothing here is regretted.","A feeling as a noun + の + あまり.","だけに cannot follow の."],"unit":3,"day":4,"step":"compare"},"u03d4.d1":{"id":"u03d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"寝坊した（　　）、^大事な試験を受けられなかった^。","options":["ばかりに","あまり","だけあって","からには"],"answer":1,"why":["One cause, and a bad result the speaker regrets.","A feeling or state taken to an extreme, as in 緊張のあまり. 寝坊した is one event.","Praise: a good result that lives up to its cause.","\"Now that…\": a decision or duty follows, not a result."],"unit":3,"day":4,"step":"drill"},"u03d4.d2":{"id":"u03d4.d2","kind":"star","type":"文の文法2","label":"Build the sentence","before":"面接では、緊張","after":"言い間違えてしまった。","tiles":["の","あまり","自分の","名前まで"],"star":2,"bank":[2,1,3,0],"hint":"あまり comes after a noun with の. Which tile can sit right after 緊張?","full":"面接では、緊張の{あまり}自分の名前まで言い間違えてしまった。","explain":"緊張 takes の before あまり, so the first two tiles are fixed. 自分の has to sit right before 名前まで.","unit":3,"day":4,"step":"drill"},"u03d4.d3":{"id":"u03d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"母は^心配の^（　　）、夜も眠れなかったそうだ。","options":["ばかりに","あまり","だけに","からには"],"answer":2,"why":["ばかりに does not follow a noun with の.","A feeling as a noun + の + あまり, and a result that goes too far.","だけに does not follow の either; it would need 心配なだけに.","からには needs a clause, and a decision or duty after it."],"unit":3,"day":4,"step":"drill"},"u03d4.d4":{"id":"u03d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"値段の安さだけで選んだ（　　）、^すぐに壊れるパソコンを買ってしまった^。","options":["だけあって","ばかりに","からには","ことから"],"answer":2,"why":["だけあって praises: the result lives up to the cause. Here the result is bad.","One careless choice, and a result the speaker regrets.","からには needs a decision or duty after it, not a result.","ことから gives grounds for a judgement or a name, not the cause of a regret."],"unit":3,"day":4,"step":"drill"},"u03d4.d5":{"id":"u03d4.d5","kind":"choice","type":"文の文法1","label":"Choose the form","q":"子どもの将来を^考える^（　　）、親が何でも決めてしまうのはよくない。","options":["あまり","ばかりに","だけに","ことから"],"answer":1,"why":["Thinking about the future too much, and something goes wrong: dictionary form + あまり.","ばかりに needs a concrete cause and a regretted result. Here the sentence judges a habit.","だけに means \"all the more because\", which does not fit a warning.","ことから gives grounds for a judgement; thinking about the future is not grounds for よくない."],"unit":3,"day":4,"step":"drill"},"u03d4.d6":{"id":"u03d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"朝、","after":"家に忘れてきた。","tiles":["急ぐ","あまり","大事な","書類を"],"star":2,"bank":[3,0,2,1],"hint":"Which verb can sit before あまり? The thing forgotten comes right before 家に.","full":"朝、急ぐ{あまり}大事な書類を家に忘れてきた。","explain":"急ぐ in the dictionary form goes before あまり. 大事な describes 書類, and 書類を is what was left at home.","unit":3,"day":4,"step":"drill"},"u03d4.e1":{"id":"u03d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"説明書をよく読まなかった（　　）、新しいパソコンを壊してしまった。","options":["だけあって","ばかりに","わりに","からには"],"answer":2,"explain":"A single cause and a result the speaker regrets. だけあって praises, わりに contrasts, and からには needs a decision after it.","unit":3,"day":4,"step":"exam"},"u03d4.e2":{"id":"u03d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"突然の知らせを聞いた彼女は、驚き（　　）、持っていたコップを落としてしまった。","options":["のあまり","ばかりに","だけあって","からには"],"answer":1,"explain":"Noun + の + あまり: a feeling so strong that something unusual happens. ばかりに and からには need a clause before them, and だけあって praises.","unit":3,"day":4,"step":"exam"},"u03d4.e3":{"id":"u03d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"うそを","after":"失ってしまった。","tiles":["ついた","ばかりに","友人の","信頼を"],"star":2,"bank":[3,0,2,1],"full":"うそをついたばかりに{友人の}信頼を失ってしまった。","explain":"ついた, ばかりに, 友人の, 信頼を. ばかりに follows the plain form, and 友人の must sit right before 信頼を.","unit":3,"day":4,"step":"exam"},"u03d4.k1":{"id":"u03d4.k1","kind":"choice","type":"語形成","label":"How the exam asks it","q":"カードの（　　）発行を申し込んだ。","options":["再","復","改","重"],"answer":1,"explain":"再 is \"again\": 再発行, 再開, 再試験. 復 appears in 復習 but is not a prefix, 改 makes 改正 and 改札, and 重 is not used this way.","unit":3,"day":4,"step":"scene"},"u03d4.r1":{"id":"u03d4.r1","kind":"choice","type":"読解・筆者の考え","q":"筆者の考えに合うのはどれか。","options":["検索することは時間のむだだ。","まず自分で考えたほうが身につく。","すぐ見つかる答えは信用できない。","わからないことはすぐ検索すべきだ。"],"short":["検索は時間のむだ","自分で考えたほうが身につく","すぐ見つかる答えは信用できない","すぐ検索すべきだ"],"answer":2,"explain":"The writer's own view follows しかし. The ending 〜のではないだろうか offers it as an opinion.","why":["Option 1 goes too far. The writer accepts that searching finds the answer in seconds.","","Option 3 is not in the text. Such answers are hard to remember, not wrong.","Option 4 is what many people do in the first sentence, not what the writer advises."],"unit":3,"day":4,"step":"skill"},"u03d5.c1":{"id":"u03d5.c1","kind":"choice","type":"文の文法1","label":"旅行の前の日","q":"準備のいい兄（　　）、もう明日の乗り換えを調べてあるだろう。","options":["のことだから","ことだし","以上は"],"answer":1,"why":["A person whose character you know (準備のいい兄), then a guess with だろう.","ことだし cannot follow a noun directly; it would need である, and it leads to a suggestion, not a guess.","以上は cannot follow a noun directly either, and it leads to a duty or resolve, not a guess about someone."],"unit":3,"day":5,"step":"compare"},"u03d5.d1":{"id":"u03d5.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"仕事の早い^彼女^（　　）、もう資料を全部そろえている^はずだ^。","options":["からには","ばかりに","のことだから","あまり"],"answer":3,"why":["からには cannot follow a noun directly, and it leads to a duty or resolve.","ばかりに cannot follow a noun directly, and it needs a result the speaker regrets.","A person you know well (仕事の早い彼女), then a confident guess with はずだ.","あまり follows a feeling noun with の, as in 心配のあまり. 彼女 is a person."],"unit":3,"day":5,"step":"drill"},"u03d5.d2":{"id":"u03d5.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"バスも^もうすぐ来る^（　　）、そろそろバス停に^行こうか^。","options":["ことだし","以上は","のことだから","ばかりに"],"answer":1,"why":["One reason (the bus is coming soon), then a casual suggestion with 〜ようか.","A bus about to come is not a commitment that binds anyone, so 以上は sounds wrong here.","のことだから follows a noun for a person, not a verb.","ばかりに needs a bad result the speaker regrets, not a suggestion."],"unit":3,"day":5,"step":"drill"},"u03d5.d3":{"id":"u03d5.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"せっかく天気もいい（　　）、^歩いて帰ることにした^。","options":["あまり","ことだし","のことだから","ばかりに"],"answer":2,"why":["あまり means a feeling or state goes too far and something unwanted happens. A calm decision does not fit.","One reason (good weather), then a decision with ことにした. も hints that there are other reasons too.","のことだから follows a noun for a person, not an adjective.","ばかりに needs a result the speaker regrets. Walking home is a choice, not a regret."],"unit":3,"day":5,"step":"drill"},"u03d5.d4":{"id":"u03d5.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^時間にルーズな^佐藤さん（　　）、今日も遅刻する^に違いない^。","options":["ことだし","以上は","ばかりに","のことだから"],"answer":4,"why":["ことだし cannot follow a noun directly, and it leads to a suggestion, not a guess.","以上は cannot follow a noun directly, and it leads to a duty or resolve.","ばかりに cannot follow a noun directly, and nothing has happened yet to regret.","Sato-san's known habit (時間にルーズ), then a guess with に違いない."],"unit":3,"day":5,"step":"drill"},"u03d5.d5":{"id":"u03d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あの","after":"時間どおりに来るだろう。","tiles":["まじめな","山田さんの","ことだから","きっと"],"star":1,"bank":[2,3,0,1],"hint":"Which tile describes the person? のことだから comes right after the person.","full":"あのまじめな山田さんの{ことだから}きっと時間どおりに来るだろう。","explain":"あの and まじめな both describe 山田さん, and 山田さんの joins ことだから. きっと sits before the guess.","unit":3,"day":5,"step":"drill"},"u03d5.d6":{"id":"u03d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"せっかく","after":"温泉にでも入って帰ろう。","tiles":["遠く","まで","来た","ことだし"],"star":2,"bank":[3,1,0,2],"hint":"ことだし follows a plain-form verb. What did we do that makes this a good idea?","full":"せっかく遠くまで来た{ことだし}温泉にでも入って帰ろう。","explain":"遠くまで来た is the reason, in the plain form before ことだし. The suggestion 帰ろう follows.","unit":3,"day":5,"step":"drill"},"u03d5.e1":{"id":"u03d5.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"子どもが好きな佐藤さん（　　）、きっといい先生になるだろう。","options":["ことだし","以上は","のことだから","ばかりに"],"answer":3,"explain":"A person whose character the speaker knows, then a guess with だろう: のことだから. ことだし, 以上は and ばかりに cannot follow a noun directly, and none of them leads to a guess like this.","unit":3,"day":5,"step":"exam"},"u03d5.e2":{"id":"u03d5.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"今日はみんな疲れている（　　）、打ち上げは来週にしませんか。","options":["のことだから","ことだし","あまり","ばかりに"],"answer":2,"explain":"One reason, then a suggestion (〜ませんか): ことだし. のことだから follows a noun for a person. あまり and ばかりに lead to a result that has happened, not a suggestion.","unit":3,"day":5,"step":"exam"},"u03d5.e3":{"id":"u03d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"雨も","after":"帰りましょうか。","tiles":["強く","なってきた","ことだし","暗くなる前に"],"star":1,"bank":[3,0,2,1],"full":"雨も強く{なってきた}ことだし暗くなる前に帰りましょうか。","explain":"強く, なってきた, ことだし, 暗くなる前に. 強くなってきた is the reason before ことだし, and 暗くなる前に goes with 帰りましょうか.","unit":3,"day":5,"step":"exam"},"u03d5.k1":{"id":"u03d5.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"大雨の影響で、電車に_遅延_が発生しています。","options":["ちいん","ちえん","じえん","ちえい"],"answer":2,"explain":"遅 is チ as in 遅刻, and 延 is エン as in 延長: ちえん. ちいん and ちえい get 延 wrong, and じえん gets 遅 wrong.","unit":3,"day":5,"step":"scene"},"u03d5.r1":{"id":"u03d5.r1","kind":"choice","type":"課題理解","q":"男の学生はこのあとまず何をしますか。","script":["ナレーター：大学で、男の学生と女の学生が、ゼミの発表の準備について話しています。男の学生はこのあとまず何をしますか。","男：来週の発表のスライド、だいたいできたよ。ただ、グラフの数字がひとつ合わないんだ。","女：あ、それなら、田中さんにデータを確認してもらうように、さっき私から頼んでおいたよ。","男：ありがとう。じゃあ、すぐスライドを直せるね。","女：でも、田中さん、今日はアルバイトで、返事は夜になるって。","男：そうか。まあ、田中さんのことだから、今夜中にはちゃんと調べてくれるだろうね。","女：うん。じゃあ、待っている間に、配るレジュメを作っちゃえば？時間もあることだし。","男：そうだね。数字は後で入れることにして、そうするよ。先生に送るのは、全部そろってからでいいよね。","女：うん、それでいいと思う。","ナレーター：男の学生はこのあとまず何をしますか。"],"options":["田中さんにデータの確認を頼む","スライドの数字を直す","レジュメを作る","先生にレジュメを送る"],"printed":true,"short":["田中さんに頼む","スライドを直す","レジュメを作る","先生に送る"],"answer":3,"why":["Already done: the woman asked Tanaka-san a moment ago.","Later: he can fix the numbers only after Tanaka-san replies tonight.","He agrees to make the handout while he waits, and to fill in the numbers later.","Later: he will send it to the teacher once everything is ready."],"unit":3,"day":5,"step":"skill","clip":"l_u3d5"},"u03d6.c1":{"id":"u03d6.c1","kind":"choice","type":"文の文法1","label":"レストランで","q":"一流のシェフが作っている（　　）、この店の料理はどれもおいしい。","options":["ばかりに","だけあって","からには"],"answer":2,"why":["ばかりに leads to a result the speaker regrets. Good food is not one.","A cause, and a good result that lives up to it: praise.","からには leads to a resolve or a duty, not a description of the food."],"unit":3,"day":6,"step":"compare"},"u03d6.d1":{"id":"u03d6.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"財布を^ポケットに入れたまま洗濯した^（　　）、中のカードが^全部使えなくなってしまった^。","options":["だけあって","ばかりに","だけに","あまり"],"answer":2,"why":["だけあって praises. Ruined cards are not praise.","One careless act, and a bad result the speaker regrets.","だけに needs a situation that makes a feeling stronger, as in 期待していただけに. A single careless act is not one.","あまり needs a feeling or an effort taken too far. Washing a wallet by mistake is neither."],"unit":3,"day":6,"step":"drill"},"u03d6.d2":{"id":"u03d6.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^親友の結婚式だった^（　　）、仕事で出席できなかったのが^とても残念だ^。","options":["ばかりに","あまり","だけあって","だけに"],"answer":4,"why":["ばかりに would make the wedding the cause of missing it. Work was the cause.","あまり does not follow だった; it needs a feeling, as in 悲しさのあまり.","だけあって praises. 残念だ is not praise.","Because it was a best friend's wedding, missing it is all the more disappointing."],"unit":3,"day":6,"step":"drill"},"u03d6.d3":{"id":"u03d6.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この公園は、^昔ここに大きな池があった^（　　）、^「大池公園」と名付けられた^。","options":["ことから","以上は","からには","だけに"],"answer":1,"why":["A fact, and a name that comes from it.","以上は leads to a duty or a firm conclusion, not to how a place got its name.","からには leads to the speaker's resolve, not to a name.","だけに makes a feeling stronger. Giving a name is not a feeling."],"unit":3,"day":6,"step":"drill"},"u03d6.d4":{"id":"u03d6.d4","kind":"star","type":"文の文法2","label":"Build the sentence","before":"大学院に","after":"したい。","tiles":["進む","からには","世界に","通用する研究を"],"star":2,"bank":[3,1,0,2],"hint":"からには follows the plain form of a verb. What does 世界に go with?","full":"大学院に進む{からには}世界に通用する研究をしたい。","explain":"進む is the plain form before からには. 世界に goes with 通用する, and 通用する研究を is what the speaker wants to do.","unit":3,"day":6,"step":"drill"},"u03d6.d5":{"id":"u03d6.d5","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^チームの一員である^（　　）、自分の都合だけで^練習を休むべきではない^。","options":["ばかりに","以上は","だけあって","のことだから"],"answer":2,"why":["ばかりに leads to a result the speaker regrets, not to べきではない.","Given that you are a member, there is a duty: 以上は ... べきではない.","だけあって praises a result that has happened. べきではない is advice, not praise.","のことだから follows a noun for a person, not である, and leads to a guess."],"unit":3,"day":6,"step":"drill"},"u03d6.d6":{"id":"u03d6.d6","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^よく気がつく^田中さん（　　）、もう飲み物を用意してくれている^だろう^。","options":["ばかりに","ことだし","のことだから","からには"],"answer":3,"why":["ばかりに cannot follow a noun directly, and it leads to a regretted result, not a guess.","ことだし cannot follow a noun directly, and it leads to a suggestion, not a guess.","Someone whose character you know, then a guess with だろう.","からには cannot follow a noun directly, and it leads to a resolve, not a guess."],"unit":3,"day":6,"step":"drill"},"u03d6.d7":{"id":"u03d6.d7","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^みんなそろった^（　　）、そろそろ^始めましょうか^。","options":["のことだから","あまり","ばかりに","ことだし"],"answer":4,"why":["のことだから follows a noun for a person (山田さんのことだから), not a verb.","あまり needs a feeling taken too far, and it cannot lead to a suggestion.","ばかりに leads to a regretted result, never to a suggestion.","One reason, then a suggestion (〜ましょうか)."],"unit":3,"day":6,"step":"drill"},"u03d6.d8":{"id":"u03d6.d8","kind":"star","type":"文の文法2","label":"Build the sentence","before":"彼は","after":"ことに挑戦しなくなった。","tiles":["失敗を","恐れる","あまり","新しい"],"star":1,"bank":[3,2,0,1],"hint":"Which verb sits before あまり? What does 新しい describe?","full":"彼は失敗を恐れる{あまり}新しいことに挑戦しなくなった。","explain":"失敗を恐れる is the fear, in the dictionary form before あまり. 新しい describes こと.","unit":3,"day":6,"step":"drill"},"u03d6.e1":{"id":"u03d6.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"本日は貸切（　　）、一般のお客様はご利用いただけません。","options":["ことから","だけに","につき","あまり"],"answer":3,"explain":"A formal notice: noun + につき. ことから would need な or である after a noun, あまり would need の, and だけに (all the more) does not fit a notice.","unit":3,"day":6,"step":"exam"},"u03d6.e2":{"id":"u03d6.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"このホテルは百年の歴史がある（　　）、ロビーの家具も一つ一つが立派だ。","options":["だけあって","ばかりに","ことだし","からには"],"answer":1,"explain":"A cause, and praise that lives up to it: だけあって. ばかりに needs a regretted result, ことだし a suggestion, and からには a resolve or a duty.","unit":3,"day":6,"step":"exam"},"u03d6.e3":{"id":"u03d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"マラソンに","after":"やめるわけにはいかない。","tiles":["出る","と決めた","以上は","途中で"],"star":2,"bank":[3,0,2,1],"full":"マラソンに出ると決めた{以上は}途中でやめるわけにはいかない。","explain":"出る, と決めた, 以上は, 途中で. 以上は follows the plain form 決めた, and 途中で goes with やめる.","unit":3,"day":6,"step":"exam"},"u03d6.k1":{"id":"u03d6.k1","kind":"choice","type":"表記","label":"How the exam asks it","q":"借りた本は、一階のカウンターに_へんきゃく_してください。","options":["変却","返脚","返却","反却"],"answer":3,"explain":"返 is \"give back\", as in 返事 and 返す, and 却 is キャク: 返却. 変 means \"change\", 反 means \"against\", and 脚 (キャク) means \"leg\".","unit":3,"day":6,"step":"scene"},"u03d6.r1":{"id":"u03d6.r1","kind":"choice","type":"読解・主張","q":"筆者がいちばん言いたいことは何か。","options":["図書館は、もっと遅くまで開くべきだ。","借りた本は、決められた日までに返すべきだ。","人気のある本は、予約しないと借りられない。","図書館の利用者を、もっと増やすべきだ。"],"short":["もっと遅くまで開くべき","決められた日までに返すべき","人気の本は予約が必要","利用者を増やすべき"],"answer":2,"explain":"After ただ, the writer turns to a problem: books returned late. The view is given with 〜当然ではないだろうか and repeated at the end with その意識 and 〜と思う.","why":["Option 1 is background. The library already opens until nine, and the writer does not ask for more.","","Option 3 is not said. The text says popular books have many reservations, not that you must reserve them.","Option 4 is background. The writer reports that users have increased but does not argue for more."],"unit":3,"day":6,"step":"skill"},"u03t.1":{"id":"u03t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"来月でアパートの_契約_が切れる。","options":["けやく","げいやく","けいやく","けいやっく"],"answer":3,"explain":"契約 is けいやく: 契 is ケイ with a long vowel, and 約 is ヤク as in 約束. けやく shortens the vowel, げいやく adds voicing, and けいやっく adds a small っ.","unit":3,"step":"test"},"u03t.2":{"id":"u03t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"四月から、このバスの_運賃_が上がる。","options":["うんちん","うんじん","うちん","うんしん"],"answer":1,"explain":"運賃 is うんちん: 運 is ウン, and 賃 is チン as in 家賃. うんじん adds voicing, うちん drops the ん, and うんしん misreads 賃.","unit":3,"step":"test"},"u03t.3":{"id":"u03t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"この書類の下の欄に、_しょめい_をお願いします。","options":["暑名","署名","緒名","諸名"],"answer":2,"explain":"A signature is 署名. 暑, 緒 and 諸 share the part 者 and look alike, but 暑名, 緒名 and 諸名 are not words.","unit":3,"step":"test"},"u03t.4":{"id":"u03t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"_しんせいしょ_に必要なことを記入して、窓口に出してください。","options":["申精書","伸請書","申清書","申請書"],"answer":4,"explain":"An application form is 申請書: 申 \"say\" and 請 \"request\". 精 and 清 sound like セイ but do not make this word, and 伸 is \"stretch\", not 申.","unit":3,"step":"test"},"u03t.5":{"id":"u03t.5","kind":"choice","type":"語形成","label":"Word formation","q":"銀行の窓口で振り込むと、手数（　　）が三百円かかる。","options":["料","費","代","賃"],"answer":1,"explain":"A handling fee is 手数料. 料 makes many fees (送料, 入場料). 手数費, 手数代 and 手数賃 are not words.","unit":3,"step":"test"},"u03t.6":{"id":"u03t.6","kind":"choice","type":"語形成","label":"Word formation","q":"（　　）記入の欄がある申請書は、受け付けられません。","options":["不","非","未","反"],"answer":3,"explain":"未 means \"not yet\": 未記入 is a box not yet filled in. 不記入, 非記入 and 反記入 are not words.","unit":3,"step":"test"},"u03t.7":{"id":"u03t.7","kind":"choice","type":"文脈規定","label":"Word in context","q":"大雪のため、この路線は午後から（　　）となった。","options":["休業","運休","休講","欠勤"],"answer":2,"explain":"A train line that stops running is 運休. 休業 is a shop or business closing, 休講 is a cancelled class, and 欠勤 is a worker staying off work.","unit":3,"step":"test"},"u03t.8":{"id":"u03t.8","kind":"choice","type":"文脈規定","label":"Word in context","q":"このアパートは、二年ごとに契約を（　　）する決まりになっている。","options":["署名","記入","発行","更新"],"answer":4,"explain":"A contract is renewed: 契約を更新する. You sign a document (書類に署名する), fill in a form (用紙に記入する) and a certificate is issued (発行する), but none of these takes 契約を.","unit":3,"step":"test"},"u03t.9":{"id":"u03t.9","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この町は、昔から焼き物作りが盛んである（　　）、「焼き物の町」として知られている。","options":["につき","ことから","からには","ばかりに"],"answer":2,"explain":"A fact gives the grounds for a name or reputation (〜として知られている): ことから. につき follows a noun on a notice, からには needs a resolve or duty after it, and ばかりに needs a result the speaker regrets.","unit":3,"step":"test"},"u03t.10":{"id":"u03t.10","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ただいま準備中（　　）、もうしばらくお待ちください。","options":["あまり","だけあって","につき","のことだから"],"answer":3,"explain":"A noun + につき gives the reason on a notice, and a polite request can follow. あまり needs a feeling noun with の, だけあって praises a result, and のことだから needs a person and a guess.","unit":3,"step":"test"},"u03t.11":{"id":"u03t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"一度引き受けた（　　）、途中で投げ出すわけにはいかない。","options":["わりに","あまり","だけあって","以上"],"answer":4,"explain":"Having taken the job on is a fact that brings a duty, and わけにはいかない states it: 以上. わりに sets up a contrast, あまり needs a feeling taken too far, and だけあって praises a result that has come about.","unit":3,"step":"test"},"u03t.12":{"id":"u03t.12","kind":"choice","type":"文の文法1","label":"Choose the form","q":"大学院に進む（　　）、研究者として認められるような成果を出したい。","options":["からには","ばかりに","あまり","ことから"],"answer":1,"explain":"Going on to graduate school commits the speaker, and a strong wish follows: からには. ばかりに needs a regretted result, あまり a feeling taken too far, and ことから gives grounds for a judgement, not a wish.","unit":3,"step":"test"},"u03t.13":{"id":"u03t.13","kind":"choice","type":"文の文法1","label":"Choose the form","q":"さすがプロの料理人（　　）、包丁の使い方が私たちとはまったく違う。","options":["にしては","ばかりに","だけあって","ことだし"],"answer":3,"explain":"さすが with a status, and skill that lives up to it: だけあって, which can follow a noun directly. にしては says the result falls short of what you expect, which clashes with さすが. ばかりに and ことだし would need である after a noun, and neither praises.","unit":3,"step":"test"},"u03t.14":{"id":"u03t.14","kind":"choice","type":"文の文法1","label":"Choose the form","q":"苦労してやっと手に入れたチケット（　　）、なくしたときのショックは大きかった。","options":["だけあって","だけに","からには","ことだし"],"answer":2,"explain":"The harder it was to get, the bigger the shock: だけに, which can follow a noun directly. だけあって praises, and a shock is not praise. からには and ことだし would need である after a noun, and they lead to a resolve or a suggestion, not a feeling.","unit":3,"step":"test"},"u03t.15":{"id":"u03t.15","kind":"choice","type":"文の文法1","label":"Choose the form","q":"私が余計なことを言った（　　）、二人はけんかになってしまった。","options":["だけあって","からには","あまり","ばかりに"],"answer":4,"explain":"One careless remark, and a bad result the speaker regrets (〜てしまった): ばかりに. だけあって praises, からには needs a resolve or duty after it, and あまり needs a feeling or effort taken too far, which one remark is not.","unit":3,"step":"test"},"u03t.16":{"id":"u03t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"試験に","after":"泣き出してしまった。","tiles":["合格した","うれしさの","あまり","思わず"],"star":2,"bank":[3,1,0,2],"full":"試験に合格したうれしさの{あまり}思わず泣き出してしまった。","explain":"合格した, うれしさの, あまり, 思わず. 試験に needs its verb 合格した, which describes うれしさ. The feeling noun takes の before あまり, and 思わず goes with the result 泣き出してしまった.","unit":3,"step":"test"},"u03t.17":{"id":"u03t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あの","after":"このケーキもすぐに食べてしまうだろう。","tiles":["甘いものに","目がない","母の","ことだから"],"star":1,"bank":[2,3,0,1],"full":"あの甘いものに{目がない}母のことだからこのケーキもすぐに食べてしまうだろう。","explain":"甘いものに, 目がない, 母の, ことだから. 甘いものに目がない (loves sweets) describes 母, the person takes の before ことだから, and a guess with だろう follows.","unit":3,"step":"test"},"u03t.18":{"id":"u03t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"メンバーも全員","after":"ましょうか。","tiles":["そろった","ことだし","会議を","始め"],"star":2,"bank":[2,0,3,1],"full":"メンバーも全員そろったことだし{会議を}始めましょうか。","explain":"そろった, ことだし, 会議を, 始め. 全員そろった is the reason in the plain form before ことだし, and the suggestion 会議を始めましょうか follows. 始め must sit right before ましょうか.","unit":3,"step":"test"},"u03t.19":{"id":"u03t.19","kind":"choice","type":"読解・内容理解","label":"Short passage","q":"図書館が休館するのはなぜか。","options":["返却ポストを新しくするため","本を整理するため","空調設備の工事をするため","CDやDVDのケースを直すため"],"answer":3,"passage":"館内の空調設備工事につき、7月10日から7月23日まで臨時休館いたします。休館中に本を返却される方は、正面入口横の返却ポストをご利用ください。ただし、CDやDVDはケースが割れるおそれがあるため、ポストには入れず、開館後にカウンターへお返しください。なお、予約された本の受け取り期限は、休館した日数の分だけ延長いたします。ご不便をおかけしますが、ご理解をお願いいたします。","short":["ポストを新しくする","本を整理する","空調の工事","ケースを直す"],"explain":"The first sentence gives the reason with につき: 空調設備工事につき. The post box, sorting books and repairing cases are not given as reasons; cases are mentioned only as a risk in the post box.","unit":3,"step":"test"},"u03t.20":{"id":"u03t.20","kind":"choice","type":"読解・内容理解","label":"Short passage","q":"休館中にDVDを返したい人は、どうすればいいか。","options":["正面入口横の返却ポストに入れる","開館してからカウンターに返す","休館中にカウンターに持っていく","受け取り期限の延長を申し込む"],"answer":2,"passage":"館内の空調設備工事につき、7月10日から7月23日まで臨時休館いたします。休館中に本を返却される方は、正面入口横の返却ポストをご利用ください。ただし、CDやDVDはケースが割れるおそれがあるため、ポストには入れず、開館後にカウンターへお返しください。なお、予約された本の受け取り期限は、休館した日数の分だけ延長いたします。ご不便をおかけしますが、ご理解をお願いいたします。","short":["ポストに入れる","開館後カウンターへ","休館中にカウンターへ","延長を申し込む"],"explain":"ただし says DVDs must not go in the post box but be returned to the counter after the library reopens. The post box is for books only, the counter is closed during the closure, and the extended deadline is for reserved books and needs no request.","unit":3,"step":"test"},"u03t.21":{"id":"u03t.21","kind":"choice","type":"読解・内容理解","label":"Short passage","q":"初日に長い行列ができていたのはなぜか。","options":["パンの値段が安かったから","駅前で便利な場所にあったから","朝早くから開いていたから","テレビで何度も紹介されていたから"],"answer":4,"passage":"先日、駅前に新しいパン屋ができた。開店前からテレビで何度も紹介されていただけに、初日は朝から長い行列ができていた。私も一時間並んで、いちばん人気だというクロワッサンを買ってみた。ところが、食べてみると、近所のスーパーで売っているものとそれほど変わらない。期待が大きかった分、少しがっかりしてしまった。もちろん、味の好みは人それぞれだ。ただ、これからは評判だけで店を選ぶのはやめようと思った。","short":["安かった","駅前で便利","朝早く開いた","テレビで紹介された"],"explain":"〜ていただけに links the TV coverage to the long queue on day one. The price is never mentioned, and the station and the morning are only where and when, not the reason.","unit":3,"step":"test"},"u03t.22":{"id":"u03t.22","kind":"choice","type":"読解・内容理解","label":"Short passage","q":"この経験から、筆者はどう考えたか。","options":["評判だけで店を選ばないようにしよう","人気の店には並ぶ価値がある","スーパーのパンのほうがおいしい","味の好みはだれでも同じだ"],"answer":1,"passage":"先日、駅前に新しいパン屋ができた。開店前からテレビで何度も紹介されていただけに、初日は朝から長い行列ができていた。私も一時間並んで、いちばん人気だというクロワッサンを買ってみた。ところが、食べてみると、近所のスーパーで売っているものとそれほど変わらない。期待が大きかった分、少しがっかりしてしまった。もちろん、味の好みは人それぞれだ。ただ、これからは評判だけで店を選ぶのはやめようと思った。","short":["評判だけで選ばない","並ぶ価値がある","スーパーのほうがおいしい","好みはだれでも同じ"],"explain":"The last sentence says the writer will stop choosing shops by reputation alone. The writer found the queue not worth it, said the bread was about the same as the supermarket's (not worse), and said tastes differ from person to person.","unit":3,"step":"test"},"u03t.23":{"id":"u03t.23","kind":"choice","type":"読解・内容理解","label":"Short passage","q":"筆者が発表を引き受けたのはなぜか。","options":["英語で話すのが得意だから","木村さんに頼まれたから","部長に大丈夫だと言われたから","海外の展示会に行きたかったから"],"answer":3,"passage":"来月、会社の代表として海外の展示会で発表することになった。英語で話すのは苦手なので、最初は断ろうかと思った。しかし、部長に「君なら大丈夫だ」と言われ、引き受けることにした。引き受けたからには、言い訳はできない。今は毎朝三十分早く起きて、発表の練習をしている。それを聞いた同僚の木村さんは、「心配性の君のことだから、準備しすぎて疲れないようにね」と笑っていた。確かに、そうかもしれない。","short":["英語が得意","木村さんに頼まれた","部長に大丈夫と言われた","展示会に行きたかった"],"explain":"しかし、部長に「君なら大丈夫だ」と言われ、引き受けることにした gives the reason. The writer says English is a weak point, Kimura-san only comments afterwards, and nothing is said about wanting to go abroad.","unit":3,"step":"test"},"u03t.24":{"id":"u03t.24","kind":"choice","type":"読解・内容理解","label":"Short passage","q":"木村さんは筆者についてどう思っているか。","options":["発表を断ったほうがよかった","英語の練習が足りない","朝早く起きるのが苦手だ","準備をしすぎるかもしれない"],"answer":4,"passage":"来月、会社の代表として海外の展示会で発表することになった。英語で話すのは苦手なので、最初は断ろうかと思った。しかし、部長に「君なら大丈夫だ」と言われ、引き受けることにした。引き受けたからには、言い訳はできない。今は毎朝三十分早く起きて、発表の練習をしている。それを聞いた同僚の木村さんは、「心配性の君のことだから、準備しすぎて疲れないようにね」と笑っていた。確かに、そうかもしれない。","short":["断ったほうがよかった","練習が足りない","早起きが苦手","準備をしすぎる"],"explain":"心配性の君のことだから shows Kimura-san knows the writer is a worrier and guesses they may over-prepare and tire themselves. Kimura-san says nothing about refusing, about too little practice, or about getting up early being hard.","unit":3,"step":"test"},"mock1":{"id":"mock1","kind":"choice","type":"漢字読み","label":"問題1","options":["やしなって","おぎなって","ともなって","まかなって"],"answer":2,"explain":"補う is おぎなう, to make up for what is missing. やしなう is 養う, ともなう is 伴う and まかなう is 賄う.","q":"不足している栄養を、サプリメントで_補って_いる。","step":"mock"},"mock2":{"id":"mock2","kind":"choice","type":"表記","label":"問題2","options":["対照","対称","対象","大将"],"answer":3,"explain":"対象 is the target of a survey. 対照 is a contrast, 対称 is symmetry and 大将 is a general.","q":"この調査は、20代の会社員を_たいしょう_に行われた。","step":"mock"},"mock3":{"id":"mock3","kind":"choice","type":"語形成","label":"問題3","options":["非","未","不","無"],"answer":1,"explain":"非公式 is \"unofficial\". 未 is \"not yet\" as in 未発表, 不 negates a quality as in 不便, and 無 is \"without\" as in 無料. None of those joins 公式.","q":"これはまだ（　　）公式の情報なので、発表を待ってください。","step":"mock"},"mock4":{"id":"mock4","kind":"choice","type":"文脈規定","label":"問題4","options":["見事","見本","見方","見当"],"answer":4,"explain":"見当がつかない is \"to have no idea\". 見事 is \"splendid\", 見本 is a sample and 見方 is a point of view. None of them takes がつかない.","q":"会議がいつ終わるのか、まったく（　　）がつかない。","step":"mock"},"mock5":{"id":"mock5","kind":"choice","type":"用法","label":"問題6","options":["駅に着いたら、とっくに連絡してください。","会議の時間は、とっくに過ぎていますよ。","来月、とっくに引っ越すつもりです。","この店のケーキは、とっくにおいしいです。"],"answer":2,"explain":"とっくに is \"long ago, already\", so it goes with something that is over. Sentences 1 and 3 are about the future, and sentence 4 needs 特に (とくに) or とても.","short":["着いたらとっくに連絡","とっくに過ぎている","来月とっくに引っ越す","とっくにおいしい"],"q":"次の言葉の使い方として最もよいもの：とっくに","step":"mock"},"mock6":{"id":"mock6","kind":"choice","type":"文の文法1","label":"問題7","options":["次第","上で","最中","以来"],"answer":1,"explain":"次第 follows the ます-stem and means \"as soon as\". The others cannot follow 確認し: 上で \"after doing\" takes the た-form, 最中 takes 〜ている and 以来 takes the て-form.","q":"詳しいことは、担当者に確認し（　　）、ご連絡いたします。","step":"mock"},"mock7":{"id":"mock7","kind":"choice","type":"文の文法2","label":"問題8","options":["得ない","準備","せざるを","徹夜で"],"answer":3,"explain":"〜ざるを得ない is \"have no choice but to\", and する becomes せざる. The order is 徹夜で, 準備, せざるを, 得ない.","q":"発表は明日なので、今夜は＿＿＿＿★＿＿。","step":"mock"},"mock8":{"id":"mock8","kind":"choice","type":"内容理解（短文）","label":"問題10","options":["会議中に資料を読む時間を増やすべきだ。","意見を出し合わないほうが早く終わる。","会議が長いのは内容が多いからだ。","会議を短くするには事前の準備が大切だ。"],"answer":4,"explain":"The last sentence carries the point: to shorten a meeting, change how the time before it is used. Option 1 is the problem itself, and options 2 and 3 go against the text.","short":["資料を読む時間を増やす","意見を出し合わないほうが早い","内容が多いからだ","事前の準備が大切"],"q":"筆者が最も言いたいことは何か。","passage":"会議が長いと言われる会社は少なくない。その原因は、話し合う内容よりも、準備不足にあることが多い。資料を当日配るのでは、読むだけで会議の半分が終わってしまう。前日までに資料を送り、参加者が考えをまとめてから集まれば、会議は意見を出し合う場になる。会議を短くしたいなら、まず会議前の時間の使い方を見直すべきだろう。","step":"mock"},"mock9":{"id":"mock9","kind":"choice","type":"統合理解","label":"問題12","options":["在宅勤務で、仕事の成果が上がった。","在宅勤務で、同僚と話す機会が減った。","在宅勤務で、働く時間が長くなった。","在宅勤務は、自分には合わなかった。"],"answer":2,"explain":"Only the loss of everyday talk with colleagues is in both. Better results are only in A. Longer hours and \"it did not suit me\" are only in B.","short":["成果が上がった","同僚と話す機会が減った","働く時間が長くなった","自分には合わなかった"],"q":"AとBのどちらにも書かれていることは何か。","passage":"A　在宅勤務を始めて、往復2時間の通勤がなくなった。体が楽になった分、集中して働けるようになり、成果も上がっている。ただ、同僚と気軽に話す機会が減り、ちょっとした相談がしにくくなった。\nB　在宅勤務は便利だが、私には合わなかった。家では仕事と休みの区別がつけにくく、かえって働く時間が長くなった。同僚との何気ない会話も減り、新しいアイデアが生まれにくくなった。","step":"mock"},"mock10":{"id":"mock10","kind":"choice","type":"課題理解","label":"問題1","options":["会場を予約する","資料を印刷する","参加者のリストを直す","案内メールを送る"],"answer":3,"explain":"The room is booked, and printing waits for the department head. Before the email goes out, the list needs the two new names.","q":"女の人は、このあとまず何をしなければなりませんか。","script":"会社で、男の人と女の人が、来週の説明会の準備について話しています。女の人は、このあとまず何をしなければなりませんか。\n男：来週の説明会の準備、進んでる？\n女：はい。会場の予約は済みました。あとは資料の印刷と、参加者への案内メールですね。\n男：印刷はまだ早いよ。部長が内容を少し直すって言ってたから、それを待ってからにして。\n女：わかりました。じゃあ、先に案内メールを送っておきます。\n男：あ、その前に、参加者のリストを最新のものにしておいて。昨日、2人増えたんだ。\n女：そうなんですか。じゃあ、まずそれを直します。\n女の人は、このあとまず何をしなければなりませんか。","step":"mock"},"mock11":{"id":"mock11","kind":"choice","type":"概要理解","label":"問題3","options":["商店街の家賃が上がっている問題","商店街に新しい店が増えている理由","若い人がカフェで働きたがる理由","買い物客が減り続けている原因"],"answer":2,"explain":"She explains why shops are opening: low rent and help from the other shopkeepers. Rents are low, not rising. Shoppers are coming back. The young people open cafés; nothing says they want to work in one.","short":["家賃が上がっている問題","新しい店が増えている理由","カフェで働きたがる理由","買い物客が減り続けている原因"],"q":"女の人は、何について話していますか。","script":"ラジオで、女の人が話しています。\n女：最近、駅前の商店街に新しい店が増えてきました。以前は閉まったままの店が目立っていたんですが、若い人たちが古い建物を借りて、カフェや本屋を始めているんです。家賃が安いことに加えて、商店街の人たちが開店の準備を手伝ってくれるそうで、それが店を出す決め手になっているようです。買い物客も少しずつ戻ってきているということです。\n女の人は、何について話していますか。\n1：商店街の家賃が上がっている問題\n2：商店街に新しい店が増えている理由\n3：若い人がカフェで働きたがる理由\n4：買い物客が減り続けている原因","step":"mock"},"mock12":{"id":"mock12","kind":"choice","type":"即時応答","label":"問題4","options":["いえ、遅れないように気をつけます。","はい、1時間で終わらせましょう。","ええ、かまいませんよ。何時からにしましょうか。"],"answer":3,"explain":"He asks to start the meeting an hour later. Reply 1 hears \"being late\", and reply 2 hears \"finish in an hour\".","short":["遅れないように気をつけます","1時間で終わらせましょう","かまいませんよ"],"q":"男：あの、申し訳ないんですが、明日の打ち合わせ、1時間ほど遅らせていただけないでしょうか。","script":"男：あの、申し訳ないんですが、明日の打ち合わせ、1時間ほど遅らせていただけないでしょうか。\n1：いえ、遅れないように気をつけます。\n2：はい、1時間で終わらせましょう。\n3：ええ、かまいませんよ。何時からにしましょうか。","step":"mock"},"listening":{"id":"listening","kind":"choice","type":"即時応答","label":"Quick response","q":"女：この映画、わざわざ見に来るんじゃなかった。","script":"女：この映画、わざわざ見に来るんじゃなかった。","options":["そんなにつまらなかった？","え、まだ見てないの？","じゃあ、今度見に来ようよ。"],"short":["そんなにつまらなかった？","まだ見てないの？","今度見に来ようよ"],"answer":1,"why":["Hears her regret and asks about it.","Hears a negative. She has just seen it.","Takes it as \"did not come\". 〜んじゃなかった regrets what she did."],"step":"mock"}}};
window.__ykCourseData = window.__ykCourses.N2;
